      { questionId: 'M05-FIN-Q06', moduleId: 'ACHC-ART-M05', questionText: 'When vermin are present in a patient home, you should:', options: [createOption('a', 'Refuse to provide care', false, 'You cannot refuse necessary care for vermin alone. Use proper technique.'), createOption('b', 'Use the double plastic bag method ΓÇö bring only needed supplies in double bags, leave nursing bag in car', true, 'Correct. Double-bag method protects your nursing bag from contamination.'), createOption('c', 'Set your bag on a chair with extra barrier', false, 'With vermin present, the nursing bag should stay in the car.'), createOption('d', 'Spray the area with disinfectant and proceed normally', false, 'Disinfectant spray does not address the contamination risk to your bag.')], mappedObjective: 'Apply bag technique for contaminated environments', source: 'supplemental', reviewRequired: false },
