      { questionId: 'M05-FIN-Q08', moduleId: 'ACHC-ART-M05', questionText: 'Gloves should be changed:', options: [createOption('a', 'Every hour', false, 'Gloves are changed based on patient contact, not time.'), createOption('b', 'After each patient contact', true, 'Correct. Gloves must be changed between patients, with hand washing after removal.'), createOption('c', 'Only when visibly soiled', false, 'Gloves must be changed after every patient contact regardless of visible soiling.'), createOption('d', 'At the end of the day', false, 'This would allow cross-contamination between patients.')], mappedObjective: 'Apply glove use protocol', source: 'supplemental', reviewRequired: false },
