const M06_PAGES: LessonPage[] = [
  { pageId: 'M06-P01', moduleId: 'ACHC-ART-M06', pageType: 'overview', title: 'Communication Barriers ΓÇö Module Overview',
    narrationText: `Welcome to Module Six: Communication Barriers. Effective communication is essential for safe patient care. As a home health field worker, you encounter patients with limited English proficiency, hearing and vision impairments, cognitive barriers, low health literacy, and cultural communication differences. More than forty-six million people in the United States do not speak English as their primary language. Federal laws prohibit denying or delaying medical care due to language barriers. Your agency provides qualified interpreter services at no charge to the patient. In this module you will learn about types of communication barriers including physical, language, gender, interpersonal, perceptual, cultural, and emotional barriers. You will learn agency policy on interpreter services, how to communicate with deaf and hard-of-hearing patients, non-verbal communication awareness, health literacy considerations, the teach-back method, documentation requirements, and when to escalate because communication prevents safe care. You must pass with eighty percent. Let us begin.`,
    contentHtml: `<h2>Module 6: Communication Barriers</h2><p>LEP, interpreters, hearing/vision, cognitive barriers, health literacy, teach-back, communication aids, documentation, escalation.</p><p><strong>Time:</strong> 60-70 min ┬╖ <strong>Passing:</strong> 80%</p>`,
    media: createMedia('Diverse communication scene: interpreter on phone, visual aids, sign language.', '10-second 720p: Multiple communication methods shown. Text: "Communication Barriers ΓÇö Module 6."', 'image', 'beforeNarration', 'Communication overview.'),
    duration: createDuration('ACHC-ART-M06', 'M06-P01', 'overview', 'Overview', `Module Six overview covering all communication barrier types and agency interpreter policy.`, 1),
    requiredForCompletion: true,
