const MODULE_M07: ModuleData = {
  moduleId: 'ACHC-ART-M07', title: 'Workplace & Patient Safety / OSHA',
  description: 'Field hazards, workplace violence, safe lifting, driving, environmental hazards, PPE, injury reporting, hazard escalation, patient-home safety, emergency withdrawal, documentation, supervisor responsibilities.',
  version: '1.0.0', sourceRefs: ['ACHC Training Document ΓÇö OSHA Section', 'OSHA Hazard Communication Standard'],
  policyRefs: ['RM-OS-001 (Cal/OSHA Injury & Illness Prevention Program (IIPP))'],
  formRefs: ['OSHA 300 Log', 'Incident Report', 'FDA Form 3419'], workflowRefs: ['Safety Committee Workflow', 'Injury Reporting Workflow'],
  reviewRequired: false,
  pages: [
    // 15 pages following identical structure: overview, 7 instruction with challenges, 2 doc practice, pre-assessment, final, remediation, attestation, certificate
    { pageId: 'M07-P01', moduleId: 'ACHC-ART-M07', pageType: 'overview', title: 'Workplace & Patient Safety ΓÇö Overview', narrationText: `Welcome to Module Seven: Workplace and Patient Safety. OSHA, the Occupational Safety and Health Administration, was created by the OSH Act of 1970 to prevent workers from being killed or seriously harmed at work. The law requires employers to provide working conditions free of known dangers. As a home health field worker, you face unique safety challenges because you work in uncontrolled environments ΓÇö patient homes ΓÇö where hazards may include violent situations, unsanitary conditions, aggressive pets, unsafe structures, and environmental risks. In this module you will learn about OSHA rights and responsibilities, field-specific hazards, workplace violence prevention, safe lifting and transfer techniques, driving safety, environmental hazard assessment, personal protective equipment, injury and incident reporting including the eight-hour death notification requirement, hazard escalation procedures, patient home safety assessment, emergency withdrawal from unsafe settings, the SDS system for hazardous chemicals, the Safety Committee structure, and documentation requirements. You must pass with eighty percent.`, contentHtml: `<h2>Module 7: OSHA/Safety</h2>`, media: createMedia('OSHA poster and safety equipment.', '10-second 720p: Safety gear. "Module 7."', 'image', 'beforeNarration', 'Safety overview.'), duration: createDuration('ACHC-ART-M07', 'M07-P01', 'overview', 'Overview', `OSHA overview. Field hazards. Eight-hour notification. SDS system. Safety Committee.`, 1), requiredForCompletion: true },
    { pageId: 'M07-P02', moduleId: 'ACHC-ART-M07', pageType: 'instruction', title: 'OSHA Rights, Responsibilities, and Reporting', narrationText: `Workers are entitled to conditions that do not pose risk of serious harm. OSHA provides workers the right to request workplace inspections, use their rights without retaliation, receive hazard training, get copies of test results, review injury records, and get medical records. Employers must provide safe workplaces, inform employees about hazards, keep accurate injury records, post OSHA citations and injury data, notify OSHA within eight hours of a workplace death or when three or more workers go to the hospital, and not retaliate against workers using their rights. As of January 2015, all employers must report all work-related fatalities within eight hours and all inpatient hospitalizations, amputations, and eye losses within twenty-four hours. Your agency maintains OSHA 300 Log of Work-Related Injuries and Illnesses. The Safety Committee meets at least yearly to review safety information, monitor compliance, address issues, and review all work-related injuries. Minutes go to the Professional Advisory Committee and Governing Body and are maintained for five years.`, contentHtml: `<h3>OSHA Rights & Reporting</h3><ul><li>Death: notify OSHA within 8 hours</li><li>Hospitalization/amputation/eye loss: 24 hours</li><li>OSHA 300 Log maintained</li><li>Safety Committee: yearly minimum</li><li>Records: 5 years</li></ul>`, media: createMedia('OSHA reporting timeline graphic.', '10-second 720p: Timeline: death 8h, hospitalization 24h.', 'image', 'duringNarration', 'Reporting timeline.'), duration: createDuration('ACHC-ART-M07', 'M07-P02', 'instruction', 'OSHA Rights', `OSHA rights and reporting requirements. Eight-hour death notification. Safety Committee.`, 2), challenge: { challengeId: 'M07-C01', lessonId: 'M07-P02', moduleId: 'ACHC-ART-M07', title: 'OSHA Reporting', scenario: 'A coworker is seriously injured in a car accident while driving between patient visits. She is hospitalized.', narrationText: 'A coworker is hospitalized after a work-related car accident. What reporting is required?', prompt: 'What is the OSHA reporting requirement?', interactionType: 'choose-best-response', options: [createChallengeOption('a', 'Report to OSHA within 24 hours since it involves hospitalization. Document on OSHA 300 Log. Complete incident report. Notify the Safety Committee.', 'Correct. Work-related hospitalization requires OSHA notification within 24 hours, plus internal documentation and reporting.', true), createChallengeOption('b', 'No reporting needed since it was a car accident, not a workplace incident.', 'Driving between patient visits is a work-related activity. Injuries during this time are work-related.', false), createChallengeOption('c', 'Report when convenient within the next month.', 'OSHA has specific timeframes: 24 hours for hospitalization.', false)], bestPracticeAnswer: 'OSHA within 24 hours for hospitalization. OSHA 300 Log. Incident report. Safety Committee.', teachingPoint: 'Work-related injuries include those occurring during job duties such as driving between patients.', documentationPrompt: 'Complete OSHA 300 Log entry, incident report, and Safety Committee notification.', escalationPrompt: 'Administrator responsible for OSHA notification compliance.', estimatedInteractionMinutes: 4, requiredForProgression: true, graded: false, countsTowardFinalScore: false, reviewRequired: false }, requiredForCompletion: true },
    { pageId: 'M07-P03', moduleId: 'ACHC-ART-M07', pageType: 'instruction', title: 'SDS System and Hazardous Communication', narrationText: `OSHA revised its Hazard Communication Standard requiring Safety Data Sheets, or SDS, replacing the old MSDS format. SDS uses a standardized sixteen-section format. Key sections include Section One for identification, Section Two for hazard identification, Section Four for first aid, Section Eight for exposure controls and personal protection, and Section Eleven for toxicological information. Labels must include a product identifier, signal word (Danger or Warning), pictograms (square on point, black symbol on white with red frame), hazard statements, precautionary statements, and manufacturer contact information. OSHA designated eight pictograms for the standard. The signal word Danger indicates more severe hazards while Warning indicates less severe hazards. Only one signal word appears on each label. You must know how to read labels and SDS to understand chemical hazards in your work area, find first aid information, and determine proper protective equipment. OSHA requires safety training in a language employees can understand.`, contentHtml: `<h3>SDS (Safety Data Sheets)</h3><ul><li>16-section standardized format</li><li>Section 8: exposure controls, PPE</li><li>Signal words: Danger (severe) or Warning (less severe)</li><li>8 OSHA pictograms</li><li>Labels: product ID, signal word, pictogram, hazard/precautionary statements, manufacturer</li></ul>`, media: createMedia('SDS section layout and pictogram examples.', '10-second 720p: SDS format. Pictograms shown.', 'image', 'duringNarration', 'SDS layout.'), duration: createDuration('ACHC-ART-M07', 'M07-P03', 'instruction', 'SDS System', `SDS sixteen-section format. Signal words. Pictograms. Label requirements.`, 2), challenge: { challengeId: 'M07-C02', lessonId: 'M07-P03', moduleId: 'ACHC-ART-M07', title: 'SDS Knowledge Check', scenario: 'You encounter an unlabeled chemical container at a patient home that the caregiver uses for cleaning.', narrationText: 'An unlabeled chemical container is in the patient home. What do you do?', prompt: 'How do you handle the unlabeled chemical?', interactionType: 'field-safety-decision', options: [createChallengeOption('a', 'Do not use, touch, or allow the patient to be exposed to the unlabeled container. Advise the caregiver that all chemical containers must be properly labeled. Document the safety hazard. Report to your supervisor for patient home safety follow-up.', 'Correct. Unlabeled chemicals are a safety hazard. Do not use them, educate the caregiver, document, and report.', true), createChallengeOption('b', 'Smell it to identify the chemical.', 'Never smell unknown chemicals ΓÇö inhalation can cause serious harm.', false), createChallengeOption('c', 'Ignore it since it is the patient\'s home.', 'Home safety hazards must be documented and reported even in patient homes.', false)], bestPracticeAnswer: 'Do not use. Educate caregiver. Document hazard. Report to supervisor.', teachingPoint: 'All chemical containers must be properly labeled. Unlabeled chemicals are safety hazards requiring documentation and reporting.', documentationPrompt: 'Document: unlabeled chemical found, location, caregiver educated on labeling, supervisor notified.', escalationPrompt: 'Report to supervisor for home safety assessment follow-up.', estimatedInteractionMinutes: 3, requiredForProgression: true, graded: false, countsTowardFinalScore: false, reviewRequired: false }, requiredForCompletion: true },
    // M07 Pages 4-10: Field hazards, driving safety, home safety assessment, emergency withdrawal, patient safety, documentation (6 instruction + 1 scenario)
    { pageId: 'M07-P04', moduleId: 'ACHC-ART-M07', pageType: 'instruction', title: 'Field Hazards and Home Safety Assessment', narrationText: `As a field worker, your safety is priority. Common hazards include workplace violence from patients, family members, or others in the home; aggressive or unrestrained animals; unsanitary conditions including hoarding, vermin, or mold; unsafe structures such as broken stairs, lack of handrails, or poor lighting; environmental hazards like extreme temperatures, flooding, or toxic exposure; and driving hazards including weather, unfamiliar areas, and fatigue. Patient home safety assessment is part of every visit. Document hazards in the clinical record and report to your supervising nurse. All accidents or injuries must be reported and documented on an incident report. If an accident involves the patient, the physician must be notified. Safety management is the responsibility of each employee at all times. Patient and caregiver teaching includes electrical safety, bathroom safety, transfer and ambulation safety, medication storage, and equipment use. Patients must acknowledge in writing receipt of safety instructions. If you encounter an unsafe setting that poses immediate danger, you have the right to withdraw from the environment. Notify your supervisor immediately and document the circumstances.`, contentHtml: `<h3>Field Hazards</h3><ul><li>Violence, animals, unsanitary conditions, unsafe structures, environmental, driving</li></ul><h3>Home Safety Assessment</h3><ul><li>Every visit ΓÇö document hazards</li><li>Report to supervising nurse</li><li>All accidents/injuries: incident report + physician notification if patient involved</li></ul><h3>Emergency Withdrawal</h3><p>If immediate danger ΓåÆ leave ΓåÆ notify supervisor ΓåÆ document</p>`, media: createMedia('Home safety checklist with hazard icons.', '10-second 720p: Safety hazards shown. "Assess Every Home."', 'image', 'beforeNarration', 'Home safety.'), duration: createDuration('ACHC-ART-M07', 'M07-P04', 'instruction', 'Field Hazards', `Field hazards, home safety assessment, incident reporting, emergency withdrawal.`, 2), challenge: { challengeId: 'M07-C03', lessonId: 'M07-P04', moduleId: 'ACHC-ART-M07', title: 'Unsafe Home Decision', scenario: 'You arrive at a patient home and notice a strong chemical smell. The patient\'s grandson appears intoxicated and becomes verbally aggressive when you enter.', narrationText: 'Chemical smell and aggressive person at patient home. What do you do?', prompt: 'What is the correct safety response?', interactionType: 'field-safety-decision', options: [createChallengeOption('a', 'Leave the home immediately. Do not engage with the aggressive person. Once safe, call your supervisor and report the situation. Document the chemical smell and threatening behavior. Do not return until your supervisor confirms it is safe.', 'Correct. Your safety is the priority. Withdraw, report, document. The agency will coordinate a safe response.', true), createChallengeOption('b', 'Confront the grandson and ask him to leave.', 'Confronting an intoxicated, aggressive person puts you at serious risk. Withdraw to safety first.', false), createChallengeOption('c', 'Provide care quickly and leave.', 'The chemical smell and aggressive person both create immediate safety risks. Do not stay.', false)], bestPracticeAnswer: 'Withdraw immediately. Report. Document. Do not return without supervisor clearance.', teachingPoint: 'Never remain in an environment where you face immediate danger. Your safety enables you to care for patients ΓÇö an injured worker cannot help anyone.', documentationPrompt: 'Document: date, time, hazards observed (chemical smell, aggressive behavior), your actions (withdrawal), supervisor notification, plan.', escalationPrompt: 'Call supervisor immediately upon reaching safety. This may require law enforcement and Adult Protective Services involvement.', estimatedInteractionMinutes: 4, requiredForProgression: true, graded: false, countsTowardFinalScore: false, reviewRequired: false }, requiredForCompletion: true },
    { pageId: 'M07-P05', moduleId: 'ACHC-ART-M07', pageType: 'instruction', title: 'Injury Reporting and FDA Device Reporting', narrationText: `All accidents or injuries involving patients, personnel, or visitors must be reported immediately. Patient-related safety hazards are documented in the clinical record and brought to the supervising nurse's attention. A report of safety-related incidents goes to the Advisory Committee and Governing Body with causal factors and prevention actions. If an accident involves equipment malfunction and results in serious injury, illness, or death, it must be reported to the FDA within ten days. An annual FDA report summarizing incidents is filed on Form 3419. The agency reports all work-related fatalities to OSHA within eight hours and all hospitalizations, amputations, and eye losses within twenty-four hours. Every work-related injury is reviewed by the Safety Committee to determine cause, prevention, and corrective action. OSHA 300 Logs are maintained as required.`, contentHtml: `<h3>Injury Reporting</h3><ul><li>All accidents: immediate report + incident report</li><li>Patient involved: physician notification</li><li>Equipment malfunction + serious injury/death: FDA within 10 days</li><li>Annual FDA report on Form 3419</li><li>OSHA: death 8h, hospitalization 24h</li><li>Safety Committee reviews every injury</li></ul>`, media: createMedia('Reporting timeline: internal ΓåÆ FDA 10 days ΓåÆ OSHA 8/24h ΓåÆ Safety Committee review.', '10-second 720p: Timeline graphic.', 'image', 'duringNarration', 'Reporting timeline.'), duration: createDuration('ACHC-ART-M07', 'M07-P05', 'instruction', 'Injury Reporting', `FDA ten-day device reporting. OSHA eight-hour death notification. Safety Committee review.`, 2), challenge: { challengeId: 'M07-C04', lessonId: 'M07-P05', moduleId: 'ACHC-ART-M07', title: 'Equipment Malfunction', scenario: 'A patient\'s home oxygen concentrator malfunctions and the patient experiences respiratory distress before you can switch to backup portable oxygen.', narrationText: 'Equipment malfunction causes patient respiratory distress. What reporting is required?', prompt: 'What are the reporting requirements?', interactionType: 'choose-best-response', options: [createChallengeOption('a', 'Address the immediate clinical emergency (switch to backup O2, assess patient, call 911 if needed). Report equipment malfunction to supervisor. Complete incident report. Report to FDA within 10 days (equipment malfunction causing serious injury). Notify equipment supplier. Preserve the malfunctioning device for investigation.', 'Correct. Clinical emergency first, then comprehensive reporting including FDA within 10 days for equipment-related serious injury.', true), createChallengeOption('b', 'Fix the concentrator yourself.', 'Attempting to repair medical equipment is not within your scope. Address the clinical emergency and report.', false), createChallengeOption('c', 'Report to the equipment company only.', 'FDA reporting is required for equipment malfunction causing serious injury, not just manufacturer notification.', false)], bestPracticeAnswer: 'Clinical emergency ΓåÆ supervisor ΓåÆ incident report ΓåÆ FDA 10 days ΓåÆ equipment supplier ΓåÆ preserve device.', teachingPoint: 'Equipment malfunction causing serious injury triggers FDA reporting within 10 days. Always address the clinical emergency first, then complete all required reports.', documentationPrompt: 'Document: malfunction details, patient response, emergency actions, all notifications made, device preserved.', escalationPrompt: 'Notify supervisor and Administrator immediately. FDA report required within 10 days.', estimatedInteractionMinutes: 5, requiredForProgression: true, graded: false, countsTowardFinalScore: false, reviewRequired: false }, requiredForCompletion: true },
    { pageId: 'M07-P06', moduleId: 'ACHC-ART-M07', pageType: 'scenario-challenge', title: 'Safety Scenario: Complete Visit', narrationText: `Comprehensive safety scenario: you are visiting an elderly patient in a second-floor apartment with no elevator. The stairway has poor lighting and a loose handrail. The patient needs assistance transferring from bed to wheelchair for a bath. The bathroom has no grab bars and a slippery floor mat. You also notice expired medications in the kitchen. Consider every safety element as you plan this visit.`, contentHtml: `<h3>Safety Scenario</h3><p>Second floor, poor lighting, loose handrail, bed-to-wheelchair transfer, bathroom without grab bars, slippery mat, expired medications.</p>`, media: createMedia('Home safety assessment scene.', '10-second 720p: Hazards highlighted.', 'image', 'beforeNarration', 'Safety scenario.'), duration: createDuration('ACHC-ART-M07', 'M07-P06', 'scenario-challenge', 'Safety Scenario', `Multiple safety hazards in one visit.`, 5), challenge: { challengeId: 'M07-C05', lessonId: 'M07-P06', moduleId: 'ACHC-ART-M07', title: 'Complete Safety Response', scenario: 'Multiple hazards: stairs, lighting, handrail, transfer, bathroom, medications.', narrationText: 'Address all safety hazards.', prompt: 'What is your comprehensive safety plan?', interactionType: 'sequence-the-steps', options: [createChallengeOption('a', 'Document ALL hazards: stairway (lighting, handrail), bathroom (no grab bars, slippery mat), expired medications. Assess patient mobility and transfer capability. Use safe lifting/transfer technique with proper body mechanics. Place non-slip mat or remove slippery mat in bathroom. Address expired medications with patient ΓÇö remove and document. Report all hazards to supervising nurse for referral to DME for grab bars and to maintenance for stairway repair. Include hazards in care plan for all visiting staff awareness.', 'Correct. Systematic hazard identification, immediate actions where possible, documentation, and escalation for issues requiring additional resources.', true), createChallengeOption('b', 'Focus only on the patient visit and ignore the environmental hazards.', 'Environmental hazards directly affect patient and worker safety and must be documented and addressed.', false)], bestPracticeAnswer: 'Document all hazards, take immediate corrective actions, safe transfer technique, report for resolution, update care plan.', teachingPoint: 'Every visit is a safety assessment. Document, correct what you can, and escalate what requires additional resources.', documentationPrompt: 'Document each hazard with location and description, immediate actions taken, referrals made, care plan updated.', escalationPrompt: 'Report all hazards to supervising nurse. Expired medications require physician notification.', estimatedInteractionMinutes: 5, requiredForProgression: true, graded: false, countsTowardFinalScore: false, reviewRequired: false }, requiredForCompletion: true },
    { pageId: 'M07-P07', moduleId: 'ACHC-ART-M07', pageType: 'documentation-practice', title: 'Safety Documentation Practice', narrationText: `Safety documentation includes hazard identification, incident reports, corrective actions, and safety teaching verification. For every hazard identified, document location, description, immediate action taken, report submitted to, and follow-up plan. For every incident, document date, time, circumstances, persons involved, injuries, actions taken, physician notification if patient involved, and prevention measures. Patient safety teaching documentation must include acknowledgment in writing by the patient or caregiver.`, contentHtml: `<h3>Safety Documentation</h3><ul><li>Hazard: location, description, action, report, follow-up</li><li>Incident: date, time, circumstances, injuries, actions, physician, prevention</li><li>Teaching: written acknowledgment from patient/caregiver</li></ul>`, media: createMedia('Incident report form.', '10-second 720p: Form fields.', 'image', 'beforeNarration', 'Incident form.'), duration: createDuration('ACHC-ART-M07', 'M07-P07', 'documentation-practice', 'Safety Documentation', `Hazard documentation, incident reporting, teaching verification.`, 6), challenge: { challengeId: 'M07-C06', lessonId: 'M07-P07', moduleId: 'ACHC-ART-M07', title: 'Incident Documentation', scenario: 'A patient falls during a transfer you were assisting with. No apparent injury but the patient reports hip pain.', narrationText: 'Document the patient fall incident.', prompt: 'Select the best incident documentation.', interactionType: 'documentation-practice', options: [createChallengeOption('a', '"Patient fell. Seems okay."', 'Completely inadequate incident documentation.', false), createChallengeOption('b', '"Date: [today] Time: [time]. During assisted bed-to-wheelchair transfer, patient lost balance and slid to the floor from a seated position on bed edge. Patient reports right hip pain rated 4/10. Vital signs stable. No visible deformity, bruising, or swelling noted at time of assessment. Patient able to bear weight with assistance. Physician notified at [time] ΓÇö orders received: monitor, ice to hip, report increased pain. Family notified. Incident report completed. Contributing factors: patient stated feeling dizzy upon sitting up. Prevention: assess orthostatic vitals before transfers, slower position changes. Supervisor notified."', 'Correct. Comprehensive incident documentation with all required elements.', true)], bestPracticeAnswer: 'Complete incident documentation with all required elements.', teachingPoint: 'Every patient fall requires thorough documentation, physician notification, and prevention planning.', documentationPrompt: 'Complete all incident report fields. Notify physician. Document prevention measures.', escalationPrompt: 'Physician notification required for all patient falls. Report to supervising nurse and Safety Committee.', estimatedInteractionMinutes: 5, requiredForProgression: true, graded: false, countsTowardFinalScore: false, reviewRequired: false }, requiredForCompletion: true },
    { pageId: 'M07-P08', moduleId: 'ACHC-ART-M07', pageType: 'documentation-practice', title: 'Patient Home Safety Teaching', narrationText: `Every patient and caregiver receives safety management instruction. Topics include electrical safety, environmental hazards, bathroom safety, hand washing, infection control, proper refrigeration of medications, glove use, needle disposal in non-penetrable containers, transfer and ambulation safety, and medical equipment use. Patients acknowledge receipt of these instructions in writing. You monitor their understanding and compliance on an ongoing basis. Document what was taught, how it was taught, the patient's response, and whether they demonstrated understanding. Safety hazards identified during teaching should be added to the care plan.`, contentHtml: `<h3>Patient Safety Teaching Topics</h3><p>Electrical, environmental, bathroom, hand washing, IC, refrigeration, needles, transfers, equipment</p><p><strong>Written acknowledgment required.</strong></p>`, media: createMedia('Safety teaching scene.', '10-second 720p: Teaching list.', 'image', 'beforeNarration', 'Safety teaching.'), duration: createDuration('ACHC-ART-M07', 'M07-P08', 'documentation-practice', 'Safety Teaching', `Safety teaching topics and written acknowledgment.`, 4), challenge: { challengeId: 'M07-C07', lessonId: 'M07-P08', moduleId: 'ACHC-ART-M07', title: 'Safety Teaching Verification', scenario: 'You taught a caregiver about safe needle disposal. She says she puts used needles in a coffee can.', narrationText: 'Caregiver uses a coffee can for sharps. Is this adequate?', prompt: 'What do you recommend?', interactionType: 'field-safety-decision', options: [createChallengeOption('a', 'A coffee can is a puncture-resistant container and is acceptable per state/local regulations, but an agency-provided sharps container is preferred for proper labeling and disposal. Provide an agency sharps container if available. If the coffee can must be used temporarily, ensure it has a secure lid and is labeled as containing sharps. Document the teaching and container status.', 'Correct. While a thick container may be acceptable temporarily, agency-provided labeled sharps containers are the standard. Provide one and document.', true), createChallengeOption('b', 'Tell her the coffee can is fine permanently.', 'A coffee can may work temporarily but proper sharps containers with biohazard labels are the standard.', false)], bestPracticeAnswer: 'Provide agency sharps container. Temporary alternatives must be puncture-resistant with secure lid and labeling.', teachingPoint: 'Proper sharps disposal requires labeled, puncture-resistant containers. Supply the patient with agency-provided containers.', documentationPrompt: 'Document: sharps disposal teaching, container provided, caregiver demonstrated understanding.', escalationPrompt: 'Request sharps container delivery from the office if not available at the visit.', estimatedInteractionMinutes: 3, requiredForProgression: true, graded: false, countsTowardFinalScore: false, reviewRequired: false }, requiredForCompletion: true },
