    { pageId: 'M07-P11', moduleId: 'ACHC-ART-M07', pageType: 'pre-assessment', title: 'Pre-Assessment: OSHA/Safety', narrationText: `Six questions. Not graded.`, contentHtml: `<h3>Pre-Assessment</h3>`, media: createMedia('Clipboard.', '10-second 720p: Checklist.', 'image', 'beforeNarration', 'Pre-assessment.'), duration: createDuration('ACHC-ART-M07', 'M07-P11', 'pre-assessment', 'Pre-Assessment', `Six questions.`, 8),
      assessmentQuestions: [
