        { questionId: 'M07-PRE-Q02', moduleId: 'ACHC-ART-M07', questionText: 'SDS stands for:', options: [createOption('a', 'Service Date Same', false, 'Incorrect.'), createOption('b', 'Safety Data Sheets', true, 'Correct. SDS replaced MSDS.'), createOption('c', 'Standard Disposal System', false, 'Incorrect.'), createOption('d', 'Safety Drill Schedule', false, 'Incorrect.')], mappedObjective: 'SDS definition', source: 'provided', reviewRequired: false },
        { questionId: 'M07-PRE-Q03', moduleId: 'ACHC-ART-M07', questionText: 'How many hours to notify OSHA of a workplace death?', options: [createOption('a', '24', false, '24 hours is for hospitalization/amputation/eye loss.'), createOption('b', '8', true, 'Correct. Fatalities must be reported within 8 hours.'), createOption('c', '48', false, 'Too long.'), createOption('d', '10', false, '10 days is for FDA device reporting.')], mappedObjective: 'OSHA notification timeline', source: 'provided', reviewRequired: false },
        { questionId: 'M07-PRE-Q04', moduleId: 'ACHC-ART-M07', questionText: 'When you encounter an unsafe patient home, you should:', options: [createOption('a', 'Provide care anyway', false, 'Safety first.'), createOption('b', 'Withdraw if immediate danger, notify supervisor, document', true, 'Correct.'), createOption('c', 'Call the police immediately', false, 'Police may be needed but withdrawal and supervisor notification come first.'), createOption('d', 'Ignore it', false, 'Hazards must be addressed.')], mappedObjective: 'Emergency withdrawal', source: 'supplemental', reviewRequired: false },
        { questionId: 'M07-PRE-Q05', moduleId: 'ACHC-ART-M07', questionText: 'Equipment malfunction causing serious injury is reported to the FDA within:', options: [createOption('a', '10 days', true, 'Correct.'), createOption('b', '30 days', false, 'Too long.'), createOption('c', '24 hours', false, '24 hours is OSHA hospitalization timeline.'), createOption('d', '90 days', false, 'Far too long.')], mappedObjective: 'FDA device reporting timeline', source: 'supplemental', reviewRequired: false },
