    { pageId: 'M07-P12', moduleId: 'ACHC-ART-M07', pageType: 'final-assessment', title: 'Final Assessment: OSHA/Safety', narrationText: `Twelve questions. Eighty percent.`, contentHtml: `<h3>Final Assessment</h3>`, media: createMedia('Assessment.', '10-second 720p: Score.', 'image', 'beforeNarration', 'Assessment.'), duration: createDuration('ACHC-ART-M07', 'M07-P12', 'final-assessment', 'Final Assessment', `Twelve questions.`, 15),
      assessmentQuestions: [
