        { questionId: 'M07-FIN-Q02', moduleId: 'ACHC-ART-M07', questionText: 'OSHA was created to:', options: [createOption('a', 'Enforce local and state regulations', false, 'OSHA is federal.'), createOption('b', 'To require employers to assure a safe and healthful workplace', true, 'Correct.'), createOption('c', 'Provide a place to buy protective equipment', false, 'Not OSHA\'s role.'), createOption('d', 'As a "catch all" for employee complaints', false, 'OSHA specifically addresses safety.')], mappedObjective: 'OSHA purpose', source: 'provided', reviewRequired: false },
        { questionId: 'M07-FIN-Q03', moduleId: 'ACHC-ART-M07', questionText: 'If a death of an employee occurs while working, how many hours does the agency have to notify OSHA?', options: [createOption('a', '10', false, 'Too long.'), createOption('b', '8', true, 'Correct. Work-related fatalities: 8 hours.'), createOption('c', '24', false, '24 is for hospitalization.'), createOption('d', '48', false, 'Too long.')], mappedObjective: 'OSHA death notification', source: 'provided', reviewRequired: false },
        { questionId: 'M07-FIN-Q04', moduleId: 'ACHC-ART-M07', questionText: 'Work-related inpatient hospitalizations must be reported to OSHA within:', options: [createOption('a', '8 hours', false, '8 hours is for fatalities.'), createOption('b', '24 hours', true, 'Correct. Hospitalizations, amputations, and eye losses: 24 hours.'), createOption('c', '48 hours', false, 'Too long.'), createOption('d', '10 days', false, '10 days is for FDA device reports.')], mappedObjective: 'OSHA hospitalization notification', source: 'supplemental', reviewRequired: false },
        { questionId: 'M07-FIN-Q05', moduleId: 'ACHC-ART-M07', questionText: 'Equipment malfunction causing serious injury or death is reported to:', options: [createOption('a', 'OSHA', false, 'OSHA handles workplace safety. FDA handles device reporting.'), createOption('b', 'The FDA within 10 days', true, 'Correct.'), createOption('c', 'The state only', false, 'FDA reporting is federal.'), createOption('d', 'No one unless it involves multiple patients', false, 'Single-patient events require reporting.')], mappedObjective: 'FDA device reporting', source: 'supplemental', reviewRequired: false },
        { questionId: 'M07-FIN-Q06', moduleId: 'ACHC-ART-M07', questionText: 'The two SDS signal words are:', options: [createOption('a', 'Safe and Unsafe', false, 'Not the SDS signal words.'), createOption('b', 'Danger and Warning', true, 'Correct. Danger = more severe; Warning = less severe.'), createOption('c', 'Caution and Alert', false, 'Not SDS terminology.'), createOption('d', 'Red and Yellow', false, 'These are not signal words.')], mappedObjective: 'SDS signal words', source: 'supplemental', reviewRequired: false },
        { questionId: 'M07-FIN-Q07', moduleId: 'ACHC-ART-M07', questionText: 'Safety Committee meetings are scheduled:', options: [createOption('a', 'Daily', false, 'Too frequent.'), createOption('b', 'Once yearly and as needed', true, 'Correct.'), createOption('c', 'Only after accidents', false, 'Regular schedule plus as needed.'), createOption('d', 'Every 5 years', false, 'Too infrequent.')], mappedObjective: 'Safety Committee schedule', source: 'supplemental', reviewRequired: false },
        { questionId: 'M07-FIN-Q08', moduleId: 'ACHC-ART-M07', questionText: 'If you face immediate danger in a patient home, you should:', options: [createOption('a', 'Stay and finish the visit', false, 'Your safety is the priority.'), createOption('b', 'Withdraw from the environment and notify your supervisor immediately', true, 'Correct.'), createOption('c', 'Call the police and wait inside', false, 'Withdraw first if in immediate danger.'), createOption('d', 'Document the hazard and return next week', false, 'Immediate danger requires immediate withdrawal.')], mappedObjective: 'Emergency withdrawal procedure', source: 'supplemental', reviewRequired: false },
