        { questionId: 'M07-FIN-Q12', moduleId: 'ACHC-ART-M07', questionText: 'OSHA requires safety training to be provided in:', options: [createOption('a', 'English only', false, 'If employees speak other languages, training must be in their language.'), createOption('b', 'A manner and language employees can understand', true, 'Correct.'), createOption('c', 'Written format only', false, 'Training can be verbal and practical, in the employee\'s language.'), createOption('d', 'Spanish and English only', false, 'Any language the employee needs.')], mappedObjective: 'OSHA training language requirements', source: 'supplemental', reviewRequired: false },
