const MODULE_M08: ModuleData = {
  moduleId: 'ACHC-ART-M08', title: 'Patient Rights & Responsibilities',
  description: 'Dignity, privacy, informed participation, choice, complaints, nondiscrimination, advance directives, refusal of care, abuse/neglect protections, access to information, agency responsibilities, documentation and escalation.',
  version: '1.0.0', sourceRefs: ['ACHC Training Document ΓÇö Patient Rights Section'],
  policyRefs: ['CL-PR-001 (Patient Rights & Responsibilities)'], formRefs: ['Patient Rights Acknowledgment'], workflowRefs: ['Advance Directive Workflow'],
  reviewRequired: false,
  pages: [
    { pageId: 'M08-P01', moduleId: 'ACHC-ART-M08', pageType: 'overview', title: 'Patient Rights & Responsibilities ΓÇö Overview', narrationText: `Welcome to Module Eight: Patient Rights and Responsibilities. Patient rights are an integral part of healthcare today. Protections are afforded by federal and state legislation, and as healthcare providers we must educate patients about their rights and how to exercise them. The Patient Bill of Rights is given at admission, explained by the nurse, and documented in the clinical record. Patients can exercise these rights at any time without fear of reprisal. Key rights include receiving quality care regardless of race, creed, nationality, lifestyle choice, or diagnosis; the right to refuse care; the right to be informed before care begins; privacy and PHI protection; being informed of charges; the right to safety; the right to respect; and the right to voice concerns without fear of reprisal. For every right there is a corresponding responsibility. This module covers all patient rights, how to interact professionally with clients, handling complaints and grievances from a rights perspective, advance directives, informed consent, and your documentation obligations. Eighty percent passing required.`, contentHtml: `<h2>Module 8: Patient Rights & Responsibilities</h2>`, media: createMedia('Patient Bill of Rights document.', '10-second 720p: Bill of Rights. "Module 8."', 'image', 'beforeNarration', 'Rights overview.'), duration: createDuration('ACHC-ART-M08', 'M08-P01', 'overview', 'Overview', `Patient rights overview.`, 1), requiredForCompletion: true },
    { pageId: 'M08-P02', moduleId: 'ACHC-ART-M08', pageType: 'instruction', title: 'The Patient Bill of Rights', narrationText: `The Bill of Rights must always be accessible to clients, families, the public, and staff. It is posted in the office and included in the admission packet. Upon admission, the nurse explains the Bill of Rights and gives the patient the opportunity to ask questions. Receipt is documented in the clinical record. Key rights include being fully informed in advance about care and services, choosing a healthcare provider, accessing professional services twenty-four hours a day seven days a week, being informed of charges in advance, receiving information about the scope and limitations of services, participating in the development and revision of the care plan, refusing care after consequences are fully presented, being informed about advance directives and having them honored, having property and person treated with respect and dignity, having family or guardian exercise rights when the patient is judged incompetent, identifying visiting personnel through proper identification, being free from mistreatment, neglect, and all forms of abuse, voicing grievances without fear of reprisal with resolution within thirty days, having grievances investigated, and confidentiality of all records and protected health information. If the patient or representative cannot read, the Bill of Rights will be read to them. If they do not speak English, a copy in their language will be provided.`, contentHtml: `<h3>Key Patient Rights</h3><ul><li>Informed in advance about care/services</li><li>Choose provider, 24/7 access</li><li>Informed of charges in advance</li><li>Participate in care plan</li><li>Refuse care (with consequences explained)</li><li>Advance directives honored</li><li>Dignity, respect, privacy</li><li>Free from abuse/neglect</li><li>Grievances without fear ΓÇö resolved in 30 days</li><li>Confidentiality of records/PHI</li></ul>`, media: createMedia('Bill of Rights document with key sections highlighted.', '10-second 720p: Rights list. Professional.', 'image', 'duringNarration', 'Bill of Rights.'), duration: createDuration('ACHC-ART-M08', 'M08-P02', 'instruction', 'Bill of Rights', `Comprehensive patient rights list from the Bill of Rights.`, 2), challenge: { challengeId: 'M08-C01', lessonId: 'M08-P02', moduleId: 'ACHC-ART-M08', title: 'Rights Application', scenario: 'A patient tells you she wants to stop her physical therapy because she does not feel it is helping. She asks if the agency will discharge her from all services if she refuses PT.', narrationText: 'A patient wants to refuse PT but fears being discharged from all services. How do you respond?', prompt: 'What is the rights-based response?', interactionType: 'patient-rights-response', options: [createChallengeOption('a', 'Explain that patients have the right to refuse care or treatment after the consequences are fully presented. Refusing PT does not automatically result in discharge from other services. Explain the consequences of stopping PT, document her decision, and notify the physician. Reassure her that her other services continue.', 'Correct. The right to refuse care is fundamental. Consequences must be explained. Refusal of one service does not eliminate other services.', true), createChallengeOption('b', 'Tell her she must accept all services or none.', 'Patients can refuse part of their care while accepting other parts. This is an established right.', false), createChallengeOption('c', 'Ignore her request and schedule the next PT visit.', 'Ignoring a patient\'s refusal violates their right to refuse care.', false)], bestPracticeAnswer: 'Affirm right to refuse, explain consequences, document, notify physician, reassure other services continue.', teachingPoint: 'Patients can refuse any or all services. Present consequences, document the decision, and notify the physician.', documentationPrompt: 'Document: patient stated refusal of PT, consequences discussed, patient\'s decision, physician notified, other services continue.', escalationPrompt: 'Notify physician and supervisor of service refusal.', estimatedInteractionMinutes: 4, requiredForProgression: true, graded: false, countsTowardFinalScore: false, reviewRequired: false }, requiredForCompletion: true },
    { pageId: 'M08-P03', moduleId: 'ACHC-ART-M08', pageType: 'instruction', title: 'Professional Client Interaction', narrationText: `How you interact with patients directly reflects on their rights experience. When you are in a patient's home, address the client using their name with the appropriate title. Nicknames like sweetie or honey can come across as demeaning. Terms of endearment should never be used; nicknames should only be used with the patient's permission. Treat the patient's property with respect ΓÇö you are in someone's home. Observe cultural considerations. Do not slam doors or damage property. Always introduce yourself and always wear your ID badge. Explain procedures before starting them. Answer questions honestly. If you do not know the answer, redirect to the office. Be professional and smile. When a client is upset about a concern, remain calm and objective, respond promptly, do not take it personally, remain professional, do not yell, do not name call, do not make accusations, and do not accept or assign blame.`, contentHtml: `<h3>Professional Interaction</h3><ul><li>Use name + appropriate title (no nicknames without permission)</li><li>Respect property ΓÇö you're in their HOME</li><li>Introduce yourself, wear ID badge</li><li>Explain procedures before starting</li><li>Honest answers; redirect if unsure</li></ul><h3>When Patient Is Upset</h3><ul><li>Calm, objective, prompt, professional</li><li>No yelling, name-calling, accusations, blame</li></ul>`, media: createMedia('Nurse introducing herself at patient doorstep with ID badge visible.', '10-second 720p: Professional greeting. ID badge shown. "Respect Starts at the Door."', 'image', 'beforeNarration', 'Professional interaction.'), duration: createDuration('ACHC-ART-M08', 'M08-P03', 'instruction', 'Professional Interaction', `Respectful client interaction standards.`, 2), challenge: { challengeId: 'M08-C02', lessonId: 'M08-P03', moduleId: 'ACHC-ART-M08', title: 'Interaction Scenario', scenario: 'You arrive at a patient\'s home and her daughter answers the door angrily, saying "You people never come on time and you always rush through everything!" The patient is visible in the background looking anxious.', narrationText: 'An angry family member confronts you at the door. The patient is anxious. How do you respond?', prompt: 'What is the professional response?', interactionType: 'patient-rights-response', options: [createChallengeOption('a', 'Remain calm, acknowledge her frustration without being defensive. Say something like: "I understand your concern about the timing and quality of our visits. Let me check in with your mother and provide thorough care today. I want to make sure you both feel heard. Can we discuss your specific concerns?" Document her concerns and report to your supervisor.', 'Correct. Calm, professional, non-defensive acknowledgment. Focus on the patient and care quality. Document and escalate.', true), createChallengeOption('b', 'Tell her you are not responsible for previous visits and walk past her.', 'Dismissive responses damage the patient-agency relationship and ignore legitimate concerns.', false), createChallengeOption('c', 'Argue that you are on time today.', 'Arguing is not professional and does not address the underlying concern.', false)], bestPracticeAnswer: 'Calm acknowledgment, focus on patient care, document concerns, report to supervisor.', teachingPoint: 'Professional interaction during conflict means staying calm, validating the concern, focusing on care, and escalating appropriately.', documentationPrompt: 'Document: daughter\'s concerns (exact words), your response, care provided, report to supervisor.', escalationPrompt: 'Report family concerns to supervisor for pattern assessment and resolution.', estimatedInteractionMinutes: 4, requiredForProgression: true, graded: false, countsTowardFinalScore: false, reviewRequired: false }, requiredForCompletion: true },
    // M08 Pages 4-10: Advance directives, informed consent, privacy from rights perspective, abuse protections, documentation practice, escalation (following same pattern)
    { pageId: 'M08-P04', moduleId: 'ACHC-ART-M08', pageType: 'instruction', title: 'Advance Directives and Informed Consent', narrationText: `Patients have the right to be informed about their rights under state law to formulate an advance directive. The agency complies with 42 CFR 489 regarding advance directives and provides written policies and procedures to patients. An advance directive is a legal document expressing a patient's wishes about medical treatment if they become unable to communicate. It may include a living will, healthcare power of attorney, or do-not-resuscitate order. Your responsibility is to verify whether the patient has an advance directive on file, document its existence in the clinical record, and honor the patient's wishes as directed. You do not create or advise on advance directives ΓÇö refer questions to the office or physician. Informed consent means patients must be fully informed about care and services before they begin, including disciplines involved, visit frequency, care plan modifications, and charges. The patient must have the opportunity to participate in developing and revising their care plan. Refusing care is a right, but the consequences must be fully presented first.`, contentHtml: `<h3>Advance Directives</h3><ul><li>Patient's right to formulate under state law</li><li>Agency provides written policies</li><li>Verify, document, honor</li><li>Refer questions to office/physician</li></ul><h3>Informed Consent</h3><ul><li>Fully informed before care begins</li><li>Disciplines, frequency, modifications, charges</li><li>Participate in care plan development</li><li>Refuse care after consequences presented</li></ul>`, media: createMedia('Advance directive document with nurse reviewing it with patient.', '10-second 720p: Directive document. "Honor Patient Wishes."', 'image', 'beforeNarration', 'Advance directives.'), duration: createDuration('ACHC-ART-M08', 'M08-P04', 'instruction', 'Advance Directives', `Advance directives and informed consent rights and responsibilities.`, 2), challenge: { challengeId: 'M08-C03', lessonId: 'M08-P04', moduleId: 'ACHC-ART-M08', title: 'Advance Directive Scenario', scenario: 'During a visit, a patient asks you to help her write a living will. She is worried about what would happen if she becomes unable to make decisions.', narrationText: 'A patient asks you to help write a living will. What is your role?', prompt: 'How do you respond?', interactionType: 'choose-best-response', options: [createChallengeOption('a', 'Explain that while her concern is important and valid, creating legal documents is outside your scope. Refer her to the agency office or her physician for guidance on advance directive resources, including legal aid if needed. Document her request and that you provided the referral.', 'Correct. Creating advance directives is outside your scope. Refer appropriately and document.', true), createChallengeOption('b', 'Help her write one on a piece of paper.', 'Advance directives are legal documents with specific requirements. Creating them is not within your scope.', false), createChallengeOption('c', 'Tell her not to worry about it.', 'Dismissing a patient\'s concern about end-of-life planning disrespects their autonomy.', false)], bestPracticeAnswer: 'Validate concern, explain it is outside scope, refer to office/physician/legal resources, document.', teachingPoint: 'Field workers do not create advance directives. Verify, document, honor, and refer questions appropriately.', documentationPrompt: 'Document: patient expressed interest in advance directive, referred to [office/physician], referral date.', escalationPrompt: 'Notify office to coordinate advance directive assistance.', estimatedInteractionMinutes: 3, requiredForProgression: true, graded: false, countsTowardFinalScore: false, reviewRequired: false }, requiredForCompletion: true },
    { pageId: 'M08-P05', moduleId: 'ACHC-ART-M08', pageType: 'instruction', title: 'Privacy, Dignity, and Non-Discrimination', narrationText: `Privacy, dignity, and non-discrimination are foundational rights. Patients have the right to confidentiality of all information in their record and PHI. They have the right to have their property and person treated with respect, consideration, and recognition of their dignity and individuality. They must be free of mistreatment, neglect, or any form of abuse. They have the right to identify visiting personnel through proper identification. Non-discrimination means patients receive care without regard to race, creed, nationality, origin, lifestyle choice, or diagnosis. Your responsibilities in supporting these rights include always wearing your ID badge, securing documents with patient information, using assigned identifiers instead of names when possible, never gossiping about patients, never holding conversations about patients in public, encouraging independence, and ensuring your actions reflect respect for the patient's home, possessions, and autonomy.`, contentHtml: `<h3>Privacy, Dignity, Non-Discrimination</h3><ul><li>Confidentiality of all records and PHI</li><li>Respect, consideration, dignity</li><li>Free from all abuse/neglect</li><li>Proper identification required</li><li>Care regardless of race, creed, nationality, lifestyle, diagnosis</li></ul><h3>Your Responsibilities</h3><ul><li>Wear ID badge ALWAYS</li><li>Secure documents</li><li>No gossip about patients</li><li>No public discussions about patients</li><li>Encourage independence</li></ul>`, media: createMedia('Respect-themed illustration: ID badge, secured documents, professional behavior icons.', '10-second 720p: Professional behaviors. "Dignity in Every Action."', 'image', 'beforeNarration', 'Privacy and dignity.'), duration: createDuration('ACHC-ART-M08', 'M08-P05', 'instruction', 'Privacy and Dignity', `Privacy, dignity, non-discrimination rights and worker responsibilities.`, 2), challenge: { challengeId: 'M08-C04', lessonId: 'M08-P05', moduleId: 'ACHC-ART-M08', title: 'Dignity Scenario', scenario: 'While at a restaurant after work, a coworker starts talking about a patient\'s embarrassing medical condition within earshot of other diners.', narrationText: 'A coworker discusses a patient\'s condition publicly at a restaurant. What should you do?', prompt: 'What is the correct response?', interactionType: 'privacy-security-judgment', options: [createChallengeOption('a', 'Quietly remind your coworker that discussing patient information in public violates both HIPAA and the patient\'s right to privacy. Suggest changing the subject. If the behavior continues, you may need to report it.', 'Correct. Address it quietly and immediately. Public discussion of patient information violates multiple policies and the patient\'s fundamental rights.', true), createChallengeOption('b', 'Join the conversation since you also know the patient.', 'Joining the conversation compounds the violation.', false), createChallengeOption('c', 'Ignore it since you are off duty.', 'Privacy obligations are not limited to work hours. Patient information must be protected at all times.', false)], bestPracticeAnswer: 'Remind coworker quietly, change subject, report if continues.', teachingPoint: 'Patient privacy does not end when your shift does. Public discussion of patient information is always a violation.', documentationPrompt: 'If the behavior continues, document the incident and report to supervisor/Privacy Officer.', escalationPrompt: 'Report repeated public disclosure of patient information to supervisor.', estimatedInteractionMinutes: 3, requiredForProgression: true, graded: false, countsTowardFinalScore: false, reviewRequired: false }, requiredForCompletion: true },
    { pageId: 'M08-P06', moduleId: 'ACHC-ART-M08', pageType: 'scenario-challenge', title: 'Comprehensive Patient Rights Scenario', narrationText: `You visit Mr. Chen, a competent eighty-year-old patient who lives alone. During your visit, he tells you: he wants to stop taking one of his medications because of side effects, he does not want his daughter to know about his cancer diagnosis, he would like to see his medical records, and he wants to file a complaint about a previous aide who was rude. Each of these involves a different patient right. Apply your knowledge to address all four.`, contentHtml: `<h3>Multi-Rights Scenario</h3><ol><li>Wants to refuse a medication (side effects)</li><li>Wants to restrict information from daughter (cancer diagnosis)</li><li>Wants to access medical records</li><li>Wants to file a complaint about rude aide</li></ol>`, media: createMedia('Patient discussing multiple concerns with nurse.', '10-second 720p: Four patient rights highlighted.', 'image', 'beforeNarration', 'Multi-rights scenario.'), duration: createDuration('ACHC-ART-M08', 'M08-P06', 'scenario-challenge', 'Comprehensive Rights Scenario', `Four patient rights issues in one visit.`, 5), challenge: { challengeId: 'M08-C05', lessonId: 'M08-P06', moduleId: 'ACHC-ART-M08', title: 'Multi-Rights Response', scenario: 'Address medication refusal, information restriction, records access, and complaint.', narrationText: 'Apply the correct right to each of Mr. Chen\'s four requests.', prompt: 'What is the correct response to all four?', interactionType: 'scenario-decision', options: [createChallengeOption('a', '(1) Medication: Explain consequences of stopping, document his decision, notify physician. Right to refuse. (2) Daughter: He has the right to restrict who receives his information. Document his restriction. Do not share diagnosis with daughter. (3) Records: He has the right to access his PHI. Explain the request process through the office/Privacy Officer. (4) Complaint: He has the right to voice grievances without fear. Document his complaint, submit to Administrator within agency process.', 'Correct. Each request maps to a specific patient right with a specific action: refusal, restriction, access, and grievance. All require documentation.', true), createChallengeOption('b', 'Address the complaint and tell him the other requests need to wait.', 'All four requests involve fundamental rights that should be addressed during the visit.', false)], bestPracticeAnswer: 'Address all four: refusal (consequences + physician), restriction (document + honor), access (facilitate process), grievance (document + submit).', teachingPoint: 'Multiple patient rights may be invoked in a single visit. Know the action required for each right and document everything.', documentationPrompt: 'Document each: medication refusal with consequences discussed, information restriction on cancer diagnosis, records access request facilitated, complaint documented and submitted.', escalationPrompt: 'Physician for medication refusal. Office for records request. Administrator for complaint.', estimatedInteractionMinutes: 5, requiredForProgression: true, graded: false, countsTowardFinalScore: false, reviewRequired: false }, requiredForCompletion: true },
    { pageId: 'M08-P07', moduleId: 'ACHC-ART-M08', pageType: 'documentation-practice', title: 'Rights Documentation Practice', narrationText: `Documenting patient rights events is essential. Every time a patient exercises a right ΓÇö refusing care, requesting restrictions, accessing records, filing complaints ΓÇö document it in the clinical record. Include the patient's specific request in their words, your response and any education provided, any consequences discussed, who was notified (physician, supervisor, office), the patient's final decision, and your follow-up plan.`, contentHtml: `<h3>Rights Documentation</h3><p>Document every rights event: patient request, your response, education, consequences, notifications, decision, follow-up.</p>`, media: createMedia('Documentation template.', '10-second 720p: Template.', 'image', 'beforeNarration', 'Documentation.'), duration: createDuration('ACHC-ART-M08', 'M08-P07', 'documentation-practice', 'Documentation', `Rights documentation practice.`, 6), challenge: { challengeId: 'M08-C06', lessonId: 'M08-P07', moduleId: 'ACHC-ART-M08', title: 'Documentation Selection', scenario: 'Document Mr. Chen\'s medication refusal.', narrationText: 'Select the best documentation for the medication refusal.', prompt: 'Best documentation?', interactionType: 'documentation-practice', options: [createChallengeOption('a', '"Patient refuses medication."', 'Missing consequences discussed, specific medication, physician notification, and patient education.', false), createChallengeOption('b', '"Mr. Chen expressed desire to discontinue [medication name] due to side effects described as [specific symptoms]. Consequences of discontinuation discussed: [specific risks]. Mr. Chen states he understands the risks and wishes to stop the medication. Patient\'s right to refuse care honored. Physician Dr. [name] notified at [time] ΓÇö orders received: [discontinue/alternative]. Documented in care plan. Follow-up: monitor for [relevant changes] at next visit."', 'Correct. Complete rights-based documentation.', true)], bestPracticeAnswer: 'Complete documentation with specific details, consequences, physician notification, and follow-up.', teachingPoint: 'Rights documentation must include the specific right exercised, education provided, notifications made, and follow-up plan.', documentationPrompt: 'Use this format for all rights events.', escalationPrompt: 'Physician notification is required for all care refusals.', estimatedInteractionMinutes: 5, requiredForProgression: true, graded: false, countsTowardFinalScore: false, reviewRequired: false }, requiredForCompletion: true },
    { pageId: 'M08-P08', moduleId: 'ACHC-ART-M08', pageType: 'documentation-practice', title: 'Patient Responsibilities and Agency Obligations', narrationText: `For every right there is a responsibility. Patients are responsible for providing accurate health information, following the agreed care plan, informing the agency of changes in condition, treating healthcare workers with respect, using equipment safely as instructed, and notifying the agency if they will not be available for scheduled visits. The agency is responsible for providing care within its capability, informing patients of charges, providing twenty-four seven access to professional services, ensuring continuity of care, informing patients of anticipated termination or transfer, and ensuring all staff are identifiable and qualified.`, contentHtml: `<h3>Patient Responsibilities</h3><ul><li>Accurate health information</li><li>Follow care plan</li><li>Report changes</li><li>Treat workers with respect</li><li>Safe equipment use</li><li>Notify of unavailability</li></ul><h3>Agency Responsibilities</h3><ul><li>Provide capable care</li><li>Inform of charges</li><li>24/7 professional access</li><li>Continuity of care</li><li>Inform of termination/transfer</li><li>Identifiable, qualified staff</li></ul>`, media: createMedia('Two-column graphic: Patient Responsibilities | Agency Responsibilities.', '10-second 720p: Two columns.', 'image', 'beforeNarration', 'Responsibilities.'), duration: createDuration('ACHC-ART-M08', 'M08-P08', 'documentation-practice', 'Responsibilities', `Patient and agency responsibilities.`, 4), challenge: { challengeId: 'M08-C07', lessonId: 'M08-P08', moduleId: 'ACHC-ART-M08', title: 'Responsibility Balance', scenario: 'A patient consistently refuses to let you take vital signs but then complains that the agency is not monitoring his health properly.', narrationText: 'A patient refuses vital signs but complains about inadequate monitoring. How do you address this?', prompt: 'How do you balance the right to refuse with the need for monitoring?', interactionType: 'patient-rights-response', options: [createChallengeOption('a', 'Explain that he has the right to refuse vital signs, but his responsibility includes cooperating with the care plan that was developed with his input. Document each refusal, the consequences discussed, and his complaint. Notify the physician about the pattern of refusal and the monitoring gap. Work with the patient to find an acceptable alternative ΓÇö perhaps he is willing to self-monitor and report.', 'Correct. Balance the right to refuse with education about responsibilities. Document, notify physician, explore alternatives.', true), createChallengeOption('b', 'Force the vital signs since he is complaining anyway.', 'Forcing any procedure violates the right to refuse care.', false)], bestPracticeAnswer: 'Educate on responsibility, document refusals, notify physician, explore alternatives.', teachingPoint: 'Rights and responsibilities work together. When a patient exercises one, help them understand the other.', documentationPrompt: 'Document: pattern of refusal, consequences discussed each time, complaint about monitoring, physician notified, alternative plan explored.', escalationPrompt: 'Notify physician about monitoring gap due to repeated vital sign refusal.', estimatedInteractionMinutes: 4, requiredForProgression: true, graded: false, countsTowardFinalScore: false, reviewRequired: false }, requiredForCompletion: true },
    // M08 Pre-Assessment, Final, Remediation, Attestation, Certificate
    { pageId: 'M08-P11', moduleId: 'ACHC-ART-M08', pageType: 'pre-assessment', title: 'Pre-Assessment: Patient Rights', narrationText: `Six questions. Not graded.`, contentHtml: `<h3>Pre-Assessment</h3>`, media: createMedia('Clipboard.', '10-second 720p: Checklist.', 'image', 'beforeNarration', 'Pre-assessment.'), duration: createDuration('ACHC-ART-M08', 'M08-P11', 'pre-assessment', 'Pre-Assessment', `Six questions.`, 8),
      assessmentQuestions: [
        { questionId: 'M08-PRE-Q01', moduleId: 'ACHC-ART-M08', questionText: 'Key items to remember about the Patient Bill of Rights include:', options: [createOption('a', 'The rights can be exercised at anytime', false, 'This is correct but incomplete.'), createOption('b', 'The patient always has the right to refuse care', false, 'Correct but incomplete.'), createOption('c', 'The patient has the right to be treated with respect', false, 'Correct but incomplete.'), createOption('d', 'All of the above', true, 'Correct. All three are key elements of the Bill of Rights.')], mappedObjective: 'Identify patient rights', source: 'provided', reviewRequired: false },
        { questionId: 'M08-PRE-Q02', moduleId: 'ACHC-ART-M08', questionText: 'When addressing patients, you should:', options: [createOption('a', 'Use nicknames like sweetie or honey', false, 'Terms of endearment should never be used.'), createOption('b', 'Use their name with appropriate title', true, 'Correct.'), createOption('c', 'Call them by their diagnosis', false, 'Never.'), createOption('d', 'It doesn\'t matter', false, 'Professional address matters.')], mappedObjective: 'Apply professional interaction', source: 'supplemental', reviewRequired: false },
        { questionId: 'M08-PRE-Q03', moduleId: 'ACHC-ART-M08', questionText: 'Patients must be informed about advance directives:', options: [createOption('a', 'Only if they ask', false, 'It is the agency\'s responsibility to inform.'), createOption('b', 'Per state law and agency policy', true, 'Correct.'), createOption('c', 'Only at discharge', false, 'At admission.'), createOption('d', 'Never', false, 'It is a right.')], mappedObjective: 'Identify advance directive rights', source: 'supplemental', reviewRequired: false },
        { questionId: 'M08-PRE-Q04', moduleId: 'ACHC-ART-M08', questionText: 'The Bill of Rights is given to patients:', options: [createOption('a', 'On or before admission', true, 'Correct.'), createOption('b', 'At discharge', false, 'Must be provided at or before admission.'), createOption('c', 'Only if requested', false, 'Every patient receives it.'), createOption('d', 'After the first week', false, 'At or before admission.')], mappedObjective: 'Identify when rights are provided', source: 'supplemental', reviewRequired: false },
        { questionId: 'M08-PRE-Q05', moduleId: 'ACHC-ART-M08', questionText: 'Grievances must be resolved and the patient notified within:', options: [createOption('a', '10 days', false, '10 days is the written response time.'), createOption('b', '30 days', true, 'Correct per the Bill of Rights.'), createOption('c', '60 days', false, 'Too long.'), createOption('d', '90 days', false, 'Too long.')], mappedObjective: 'Identify grievance timeline', source: 'supplemental', reviewRequired: false },
        { questionId: 'M08-PRE-Q06', moduleId: 'ACHC-ART-M08', questionText: 'You should always wear your:', options: [createOption('a', 'Favorite shirt', false, 'Not relevant.'), createOption('b', 'ID badge', true, 'Correct. Patients have the right to identify visiting personnel through proper identification.'), createOption('c', 'Watch', false, 'Not a requirement.'), createOption('d', 'Sunglasses', false, 'Not relevant.')], mappedObjective: 'Apply identification requirements', source: 'supplemental', reviewRequired: false },
      ], requiredForCompletion: true },
    { pageId: 'M08-P12', moduleId: 'ACHC-ART-M08', pageType: 'final-assessment', title: 'Final Assessment: Patient Rights', narrationText: `Twelve questions. Eighty percent.`, contentHtml: `<h3>Final Assessment</h3>`, media: createMedia('Assessment.', '10-second 720p: Score.', 'image', 'beforeNarration', 'Assessment.'), duration: createDuration('ACHC-ART-M08', 'M08-P12', 'final-assessment', 'Final Assessment', `Twelve questions.`, 15),
      assessmentQuestions: [
        { questionId: 'M08-FIN-Q01', moduleId: 'ACHC-ART-M08', questionText: 'Key items to remember about the Patient Bill of Rights are:', options: [createOption('a', 'The rights can be exercised at anytime', false, 'Correct but incomplete.'), createOption('b', 'The patient always has the right to refuse care', false, 'Correct but incomplete.'), createOption('c', 'The patient has the right to be treated with respect', false, 'Correct but incomplete.'), createOption('d', 'All of the above', true, 'Correct.')], mappedObjective: 'Identify key patient rights', source: 'provided', reviewRequired: false },
        { questionId: 'M08-FIN-Q02', moduleId: 'ACHC-ART-M08', questionText: 'Patients receive the Bill of Rights:', options: [createOption('a', 'At discharge', false, 'At or before admission.'), createOption('b', 'On or before admission', true, 'Correct.'), createOption('c', 'Only if they ask', false, 'All patients receive it.'), createOption('d', 'After their first visit', false, 'At or before admission.')], mappedObjective: 'Identify when rights are provided', source: 'supplemental', reviewRequired: false },
        { questionId: 'M08-FIN-Q03', moduleId: 'ACHC-ART-M08', questionText: 'If a patient cannot read the Bill of Rights:', options: [createOption('a', 'Skip it', false, 'The rights must be communicated regardless of literacy.'), createOption('b', 'It will be read to them', true, 'Correct. If unable to read, it will be read. If non-English speaking, provided in their language.'), createOption('c', 'Give it to their family only', false, 'The patient must receive it directly.'), createOption('d', 'Send it by mail later', false, 'Must be provided at or before admission.')], mappedObjective: 'Apply rights accessibility', source: 'supplemental', reviewRequired: false },
        { questionId: 'M08-FIN-Q04', moduleId: 'ACHC-ART-M08', questionText: 'The patient has the right to refuse care:', options: [createOption('a', 'Only with physician approval', false, 'Refusal is the patient\'s right regardless of physician opinion.'), createOption('b', 'After the consequences are fully presented', true, 'Correct.'), createOption('c', 'Never', false, 'Refusal is a fundamental right.'), createOption('d', 'Only for non-essential services', false, 'Refusal applies to any service.')], mappedObjective: 'Apply refusal of care rights', source: 'supplemental', reviewRequired: false },
        { questionId: 'M08-FIN-Q05', moduleId: 'ACHC-ART-M08', questionText: 'Terms of endearment like "sweetie" or "honey" should:', options: [createOption('a', 'Be used to make patients comfortable', false, 'They can be perceived as demeaning.'), createOption('b', 'Never be used; use name with appropriate title', true, 'Correct.'), createOption('c', 'Be used only with elderly patients', false, 'Never with any patient.'), createOption('d', 'Be used if the patient seems to like it', false, 'Professional address is the standard.')], mappedObjective: 'Apply professional interaction standards', source: 'supplemental', reviewRequired: false },
        { questionId: 'M08-FIN-Q06', moduleId: 'ACHC-ART-M08', questionText: 'The agency must honor a patient\'s advance directive:', options: [createOption('a', 'Only if the family agrees', false, 'The patient\'s directive is honored regardless of family agreement.'), createOption('b', 'Yes, per policy and law', true, 'Correct. The agency must honor advance directives in providing care.'), createOption('c', 'Only if the physician agrees', false, 'The directive reflects the patient\'s wishes.'), createOption('d', 'Only during business hours', false, 'Advance directives are honored at all times.')], mappedObjective: 'Apply advance directive requirements', source: 'supplemental', reviewRequired: false },
        { questionId: 'M08-FIN-Q07', moduleId: 'ACHC-ART-M08', questionText: 'Patients have the right to voice grievances and know they will be resolved within:', options: [createOption('a', '10 days', false, '10 days is the initial written response.'), createOption('b', '30 days', true, 'Correct. Per the Bill of Rights, grievances will be resolved and patient notified within 30 days.'), createOption('c', '60 days', false, 'Too long.'), createOption('d', '90 days', false, 'Too long.')], mappedObjective: 'Identify grievance resolution timeline', source: 'supplemental', reviewRequired: false },
        { questionId: 'M08-FIN-Q08', moduleId: 'ACHC-ART-M08', questionText: 'Patients must be able to identify visiting personnel through:', options: [createOption('a', 'Their car', false, 'Not a reliable identifier.'), createOption('b', 'Proper identification (ID badge)', true, 'Correct. Wearing ID is always required.'), createOption('c', 'Their uniform color', false, 'Not sufficient.'), createOption('d', 'A phone call ahead', false, 'Calling is courteous but ID is the right.')], mappedObjective: 'Apply identification requirements', source: 'supplemental', reviewRequired: false },
        { questionId: 'M08-FIN-Q09', moduleId: 'ACHC-ART-M08', questionText: 'When a patient is judged incompetent, their rights are exercised by:', options: [createOption('a', 'The agency', false, 'The agency does not exercise patient rights.'), createOption('b', 'The person appointed by law (family/guardian)', true, 'Correct.'), createOption('c', 'No one ΓÇö rights are suspended', false, 'Rights are never suspended; they are exercised by the legal representative.'), createOption('d', 'The physician only', false, 'The legal representative, not the physician alone.')], mappedObjective: 'Identify rights for incompetent patients', source: 'supplemental', reviewRequired: false },
        { questionId: 'M08-FIN-Q10', moduleId: 'ACHC-ART-M08', questionText: 'Patients must be informed of charges:', options: [createOption('a', 'After services are provided', false, 'Must be informed IN ADVANCE.'), createOption('b', 'In advance of care being provided, both orally and in writing', true, 'Correct.'), createOption('c', 'Only if they ask', false, 'Proactive disclosure is required.'), createOption('d', 'Only for services not covered by insurance', false, 'Charges for all services must be disclosed.')], mappedObjective: 'Apply charge disclosure requirements', source: 'supplemental', reviewRequired: false },
        { questionId: 'M08-FIN-Q11', moduleId: 'ACHC-ART-M08', questionText: 'You should NEVER:', options: [createOption('a', 'Gossip about patients or discuss them in public', true, 'Correct. Patient privacy must be maintained at all times.'), createOption('b', 'Wear your ID badge', false, 'You SHOULD always wear your badge.'), createOption('c', 'Introduce yourself at each visit', false, 'You SHOULD introduce yourself.'), createOption('d', 'Answer patient questions honestly', false, 'You SHOULD be honest.')], mappedObjective: 'Apply privacy in daily practice', source: 'supplemental', reviewRequired: false },
        { questionId: 'M08-FIN-Q12', moduleId: 'ACHC-ART-M08', questionText: 'A patient denied service solely due to inability to pay has the right to:', options: [createOption('a', 'Nothing ΓÇö services require payment', false, 'Rights protect patients from this.'), createOption('b', 'Referral to other services', true, 'Correct. The patient denied service solely on inability to pay shall have the right of referral.'), createOption('c', 'Free services from the agency', false, 'While not guaranteed free services, the patient has the right to referral.'), createOption('d', 'Legal action only', false, 'The right to referral is specified.')], mappedObjective: 'Identify referral rights', source: 'supplemental', reviewRequired: false },
      ], requiredForCompletion: true },
    { pageId: 'M08-P13', moduleId: 'ACHC-ART-M08', pageType: 'remediation', title: 'Remediation: Patient Rights', narrationText: `Review: Bill of Rights given at/before admission. Key rights: informed, choose provider, 24/7 access, charges in advance, participate in care plan, refuse care (consequences presented), advance directives honored, dignity/respect/privacy, free from abuse, grievances resolved in 30 days, confidentiality. Professional interaction: name with title, no nicknames, ID badge, explain procedures, be honest. Privacy at all times. When incompetent: legal representative exercises rights. Referral right if denied for inability to pay. Retake after review.`, contentHtml: `<h3>Remediation</h3>`, media: createMedia('Study.', '10-second 720p: Review.', 'image', 'beforeNarration', 'Remediation.'), duration: createDuration('ACHC-ART-M08', 'M08-P13', 'remediation', 'Remediation', `Review.`, 5), requiredForCompletion: true },
    { pageId: 'M08-P14', moduleId: 'ACHC-ART-M08', pageType: 'attestation', title: 'Attestation: Patient Rights', narrationText: `By signing you confirm completion and passing.`, contentHtml: `<h3>Attestation</h3><p>[Signature] ┬╖ [Checkbox] ┬╖ [Timestamp]</p>`, media: createMedia('Attestation.', '10-second 720p: Signature.', 'image', 'beforeNarration', 'Attestation.'), duration: createDuration('ACHC-ART-M08', 'M08-P14', 'attestation', 'Attestation', `Confirm.`, 2), requiredForCompletion: true },
