      duration: createDuration('ACHC-ART-M09', 'M09-P01', 'overview', 'Overview', `Corporate compliance overview. Sentencing guidelines. CCO is Administrator.`, 1), requiredForCompletion: true },
    { pageId: 'M09-P02', moduleId: 'ACHC-ART-M09', pageType: 'instruction', title: 'Compliance Program Structure and Principles',
      narrationText: `The agency's Corporate Compliance Plan operates on the basic principle of being a good corporate citizen. This means maintaining honesty and integrity in all operations, maintaining confidentiality of agency and patient records, avoiding unauthorized use of agency assets, maintaining job accountability at every level, avoiding conflicts of interest, refraining from patient abuse and reporting any abuse to appropriate authorities, maintaining appropriate patient communication, adhering to the patient's plan of care, refraining from misrepresentation with patients, contractors, or government agencies, refraining from illegal trade practices such as patient solicitation, complying with billing standards, preparing financial reports per accepted accounting practices, complying with labor and employment laws, maintaining employee privacy, maintaining a safe and harassment-free work environment, and investigating promptly any abuse, violation, or complaint. The Compliance Committee meets at least annually and includes representatives of the Board, Administrator, CEO, regional managers, CFO, and HR. The Committee reviews the CCO report, fraud alerts from the Inspector General, industry compliance topics, hotline referrals, and makes improvement recommendations. Every staff member signs a compliance acknowledgment form confirming they understand and agree to comply with the policy.`,
      contentHtml: `<h3>Compliance Principles</h3><ul><li>Honesty, integrity, confidentiality</li><li>No unauthorized asset use, no conflicts of interest</li><li>Report abuse, adhere to care plans</li><li>No misrepresentation, no patient solicitation</li><li>Billing standards, proper financial reporting</li><li>Labor law compliance, employee privacy</li><li>Safe, harassment-free workplace</li><li>Prompt investigation of violations</li></ul><h3>Structure</h3><ul><li>CCO = Administrator</li><li>Committee meets annually minimum</li><li>All employees sign acknowledgment</li></ul>`,
      media: createMedia('Compliance program organizational chart.', '10-second 720p: Org chart with CCO, Committee, reporting lines.', 'image', 'duringNarration', 'Compliance structure.'),
      duration: createDuration('ACHC-ART-M09', 'M09-P02', 'instruction', 'Compliance Structure', `Compliance principles and organizational structure.`, 2),
      challenge: { challengeId: 'M09-C01', lessonId: 'M09-P02', moduleId: 'ACHC-ART-M09', title: 'Compliance Obligation', scenario: 'A coworker tells you she noticed that a supervisor has been documenting visit times that do not match the actual times she observed visits occurring.', narrationText: 'A coworker reports potential time documentation fraud by a supervisor. What is your obligation?', prompt: 'What should you do?', interactionType: 'escalation-decision', options: [createChallengeOption('a', 'Report the concern to the Corporate Compliance Officer (Administrator) or use the agency compliance reporting channel. You are obligated to report suspected violations. Non-retaliation protections apply ΓÇö you cannot be punished for reporting in good faith.', 'Correct. Suspected documentation fraud must be reported through compliance channels. Whistleblower protections apply.', true), createChallengeOption('b', 'Ignore it since it involves a supervisor.', 'Compliance obligations apply to ALL levels. Rank does not exempt anyone from accountability.', false), createChallengeOption('c', 'Confront the supervisor directly.', 'While direct conversation may be appropriate in some situations, suspected fraud should go through formal compliance channels for proper investigation.', false)], bestPracticeAnswer: 'Report to CCO through compliance channels. Non-retaliation protection applies.', teachingPoint: 'Every employee has an obligation to report suspected compliance violations regardless of the person\'s position. Whistleblower protections exist.', documentationPrompt: 'Document what you were told, by whom, when, and that you reported to the CCO.', escalationPrompt: 'Report to CCO (Administrator). If the CCO is involved, report to the Board of Directors.', estimatedInteractionMinutes: 4, requiredForProgression: true, graded: false, countsTowardFinalScore: false, reviewRequired: false },
      requiredForCompletion: true },
    { pageId: 'M09-P03', moduleId: 'ACHC-ART-M09', pageType: 'instruction', title: 'Fraud, Waste, Abuse, and the False Claims Act',
      narrationText: `Fraud, waste, and abuse are serious compliance concerns. Fraud is intentional deception or misrepresentation to receive unauthorized benefits ΓÇö for example, billing for services not provided. Waste is the overutilization of services or practices that result in unnecessary costs. Abuse involves practices that are inconsistent with sound fiscal, business, or medical practices ΓÇö such as providing medically unnecessary services. The Federal False Claims Act imposes liability on persons and companies who defraud government programs. Submitting false claims to Medicare or Medicaid can result in treble damages plus penalties per false claim. The Stark law prohibits physician self-referral for certain designated health services. Your agency commits to abiding by the False Claims Act, the Stark Bill, state licensure requirements, and federal, state, and local civil rights laws. Individuals who have been sanctioned, excluded by any federal health program, or debarred from federal contracting will not be hired or contracted. The agency screens employment applicants and checks the National Practitioner Data Bank and Cumulative Sanction Report for applicable staff. As a field worker, your role in fraud prevention includes accurate documentation of services provided, honest reporting of visit times and activities, never billing for services not rendered, and reporting any suspected fraud through compliance channels.`,
      contentHtml: `<h3>Fraud, Waste, Abuse</h3><ul><li><strong>Fraud:</strong> Intentional deception for unauthorized benefits</li><li><strong>Waste:</strong> Overutilization, unnecessary costs</li><li><strong>Abuse:</strong> Inconsistent with sound practices, unnecessary services</li></ul><h3>False Claims Act</h3><ul><li>Liability for defrauding government programs</li><li>Treble damages + per-claim penalties</li></ul><h3>Exclusion Screening</h3><ul><li>Sanctioned/excluded individuals not hired</li><li>National Practitioner Data Bank checked</li></ul><h3>Your Role</h3><ul><li>Accurate documentation</li><li>Honest time/activity reporting</li><li>Never bill for unrendered services</li><li>Report suspected fraud</li></ul>`,
      media: createMedia('Fraud triangle diagram: Opportunity, Pressure, Rationalization. Compliance prevents all three.', '10-second 720p: Fraud triangle collapses as compliance measures appear.', 'image', 'duringNarration', 'Fraud prevention.'),
      duration: createDuration('ACHC-ART-M09', 'M09-P03', 'instruction', 'Fraud and False Claims', `Fraud, waste, abuse definitions. False Claims Act. Exclusion screening. Your documentation obligations.`, 2),
      challenge: { challengeId: 'M09-C02', lessonId: 'M09-P03', moduleId: 'ACHC-ART-M09', title: 'Documentation Integrity', scenario: 'You completed a patient visit in 30 minutes but your supervisor asks you to document it as a 60-minute visit because "that is what we bill for."', narrationText: 'Your supervisor asks you to document a 30-minute visit as 60 minutes. How do you respond?', prompt: 'What is the compliance-correct response?', interactionType: 'scenario-decision', options: [createChallengeOption('a', 'Refuse to falsify the documentation. Document the actual visit time accurately. Report the supervisor\'s request to the Corporate Compliance Officer as potential billing fraud. Your obligation is to document accurately ΓÇö falsifying records can constitute fraud under the False Claims Act.', 'Correct. Accurate documentation is a compliance obligation. A supervisor\'s request to falsify records must be reported as potential fraud.', true), createChallengeOption('b', 'Do what the supervisor says since they are your boss.', 'Following a fraudulent instruction does not protect you from liability. Both the person requesting and the person executing false documentation can face consequences.', false), createChallengeOption('c', 'Split the difference and document 45 minutes.', 'Any documentation that does not reflect reality is inaccurate and potentially fraudulent.', false)], bestPracticeAnswer: 'Document accurately. Refuse falsification. Report to CCO.', teachingPoint: 'Documentation integrity is non-negotiable. Falsifying records is fraud. Report requests to falsify through compliance channels.', documentationPrompt: 'Document the actual visit time accurately. Document the supervisor\'s request and your report to the CCO.', escalationPrompt: 'Report to CCO immediately. If the CCO is unavailable, contact the Compliance Committee or Board.', estimatedInteractionMinutes: 4, requiredForProgression: true, graded: false, countsTowardFinalScore: false, reviewRequired: false },
      requiredForCompletion: true },
    { pageId: 'M09-P04', moduleId: 'ACHC-ART-M09', pageType: 'instruction', title: 'Conflicts of Interest, Gifts, and Referrals',
      narrationText: `Conflicts of interest occur when personal interests interfere with professional obligations. The agency's compliance plan requires avoiding conflicts of interest and refraining from illegal or unfair trade practices such as patient solicitation. Gifts and kickbacks are prohibited. The provider shall not engage in kickbacks and pay-offs. Referral arrangements must be based on patient need, not financial incentives. The agency does not solicit patients through improper means. If you are offered a gift from a patient, a vendor, or a referral source, follow your agency policy. Most agencies restrict acceptance of gifts above a nominal value. Never accept cash or gifts that could be perceived as influencing your professional judgment or referral decisions. If you encounter a situation where a vendor, physician's office, or other entity offers incentives for patient referrals, report it immediately to the CCO. These arrangements may violate the Anti-Kickback Statute and the Stark law. Your integrity as a healthcare worker depends on making decisions based solely on patient need and clinical judgment, not financial incentives.`,
      contentHtml: `<h3>Conflicts of Interest</h3><ul><li>Avoid situations where personal interests interfere with professional duties</li><li>No patient solicitation</li><li>No kickbacks or pay-offs</li><li>Referrals based on patient need, not financial incentive</li></ul><h3>Gifts</h3><ul><li>Follow agency policy on gift acceptance</li><li>No cash; no gifts that could influence judgment</li><li>Report referral incentive offers to CCO</li></ul>`,
      media: createMedia('Illustration of hand refusing a gift with "No Kickbacks" text.', '10-second 720p: Hand rejecting gift. "Integrity Over Incentives."', 'image', 'beforeNarration', 'No kickbacks.'),
      duration: createDuration('ACHC-ART-M09', 'M09-P04', 'instruction', 'Conflicts and Gifts', `Conflicts of interest. No kickbacks. Referrals by patient need. Report incentive offers.`, 2),
      challenge: { challengeId: 'M09-C03', lessonId: 'M09-P04', moduleId: 'ACHC-ART-M09', title: 'Gift Scenario', scenario: 'A medical equipment vendor offers you a $100 gift card "as a thank you" for recommending their products to patients.', narrationText: 'A vendor offers you a gift card for product recommendations. What do you do?', prompt: 'Is this acceptable?', interactionType: 'scenario-decision', options: [createChallengeOption('a', 'Decline the gift card and report the offer to the CCO. Gift cards from vendors tied to product recommendations may constitute a kickback, which violates federal law and agency policy.', 'Correct. Vendor gifts tied to recommendations are potential kickbacks. Decline and report.', true), createChallengeOption('b', 'Accept it since it is just a thank-you.', 'Gifts from vendors tied to product recommendations create a conflict of interest and may violate the Anti-Kickback Statute.', false), createChallengeOption('c', 'Accept but do not tell anyone.', 'Concealing a gift from a vendor compounds the violation.', false)], bestPracticeAnswer: 'Decline and report to CCO.', teachingPoint: 'Vendor gifts tied to product recommendations are potential kickbacks. Always decline and report.', documentationPrompt: 'Document: vendor name, gift offered, your refusal, report to CCO.', escalationPrompt: 'Report to CCO immediately.', estimatedInteractionMinutes: 3, requiredForProgression: true, graded: false, countsTowardFinalScore: false, reviewRequired: false },
      requiredForCompletion: true },
    { pageId: 'M09-P05', moduleId: 'ACHC-ART-M09', pageType: 'instruction', title: 'Reporting Channels and Non-Retaliation',
      narrationText: `The agency maintains open lines of communication for compliance concerns. You can report to your supervisor, the CCO (Administrator), the Compliance Committee, or the Board of Directors. Employees can also report fraud, waste, and abuse to the OIG in HHS programs and are protected under the Whistleblower Protection Act. The agency posts information about reporting channels in the office. Non-retaliation is absolute ΓÇö filing a complaint will not subject employees to adverse action. If you observe or suspect any violation of law, regulation, or agency policy, report it promptly. The CCO tracks all violations and inquiries to identify trends. Interpretive cases that are not clear-cut must be reported up the chain of command until resolved. All employees sign a compliance acknowledgment at hire and annually. Training is provided at orientation and annually, with specialized training for high-risk areas. The agency's zero-tolerance policy for fraud or misconduct applies equally to all employees. Cooperation with investigations is required. Failure to report known violations or failure to cooperate with investigations may result in disciplinary action.`,
      contentHtml: `<h3>Reporting Channels</h3><ul><li>Supervisor ΓåÆ CCO (Administrator) ΓåÆ Compliance Committee ΓåÆ Board</li><li>External: OIG for HHS program fraud</li><li>Whistleblower Protection Act applies</li></ul><h3>Non-Retaliation</h3><p>Absolute ΓÇö no adverse action for good-faith reporting</p><h3>Your Obligations</h3><ul><li>Report violations promptly</li><li>Cooperate with investigations</li><li>Sign annual compliance acknowledgment</li><li>Complete annual compliance training</li></ul>`,
      media: createMedia('Reporting chain graphic: Employee ΓåÆ Supervisor ΓåÆ CCO ΓåÆ Committee ΓåÆ Board. External: OIG.', '10-second 720p: Reporting chain with protections highlighted.', 'image', 'duringNarration', 'Reporting channels.'),
      duration: createDuration('ACHC-ART-M09', 'M09-P05', 'instruction', 'Reporting and Non-Retaliation', `Reporting channels, whistleblower protection, non-retaliation, cooperation obligations.`, 2),
      challenge: { challengeId: 'M09-C04', lessonId: 'M09-P05', moduleId: 'ACHC-ART-M09', title: 'Reporting Channel Decision', scenario: 'You suspect the Administrator (who is also the CCO) may be involved in a billing irregularity. You are unsure who to report to since the CCO is the usual reporting target.', narrationText: 'The CCO may be involved in the suspected violation. Who do you report to?', prompt: 'What is your alternative reporting channel?', interactionType: 'escalation-decision', options: [createChallengeOption('a', 'Report directly to the Board of Directors or the Compliance Committee. When the CCO is potentially involved, the reporting chain moves to the next level. You may also report to the OIG externally. Whistleblower protections still apply.', 'Correct. When the CCO is involved, escalate to the Board or Committee. External OIG reporting is also available.', true), createChallengeOption('b', 'Do not report since there is no one to tell.', 'There are always alternative channels: Board, Committee, or external OIG.', false), createChallengeOption('c', 'Report to the CCO anyway and hope for the best.', 'Reporting to the person involved is unlikely to result in proper investigation.', false)], bestPracticeAnswer: 'Board of Directors, Compliance Committee, or external OIG when CCO is involved.', teachingPoint: 'Alternative reporting channels exist for every situation. When the CCO is involved, go to the Board or external authorities.', documentationPrompt: 'Document your concern with specifics and your reporting action.', escalationPrompt: 'Board of Directors or OIG.', estimatedInteractionMinutes: 4, requiredForProgression: true, graded: false, countsTowardFinalScore: false, reviewRequired: false },
