      challenge: { challengeId: 'M09-C05', lessonId: 'M09-P06', moduleId: 'ACHC-ART-M09', title: 'Fraud Response', scenario: 'Colleague fabricating visits asks you to stay silent.', narrationText: 'Your colleague fabricated visits and wants your silence. What do you do?', prompt: 'What is required?', interactionType: 'scenario-decision', options: [createChallengeOption('a', 'Report to the CCO immediately. Fabricating patient visits is fraud. Remaining silent makes you complicit. Document what you know: what the colleague told you, when, and any specific details about the fabricated visits. Whistleblower protection applies.', 'Correct. Fraud must be reported regardless of relationships. Silence is complicity.', true), createChallengeOption('b', 'Keep quiet to protect your colleague.', 'Silence about known fraud violates your compliance obligations and may make you liable.', false), createChallengeOption('c', 'Tell her to stop but do not report it.', 'Known fraud that goes unreported is a compliance violation for the person who knew and did not report.', false)], bestPracticeAnswer: 'Report to CCO immediately. Document. Whistleblower protections apply.', teachingPoint: 'Knowing about fraud and not reporting it makes you complicit. Your obligation is to report regardless of personal relationships.', documentationPrompt: 'Document: what was told to you, when, by whom, specific details, your report to CCO.', escalationPrompt: 'CCO immediately. This is active fraud.', estimatedInteractionMinutes: 4, requiredForProgression: true, graded: false, countsTowardFinalScore: false, reviewRequired: false },
