    { pageId: 'M09-P07', moduleId: 'ACHC-ART-M09', pageType: 'documentation-practice', title: 'Compliance Documentation and Acknowledgment',
      narrationText: `Every employee signs a Corporate Compliance Acknowledgment confirming they have been informed of and agree to comply with the agency's compliance policy. This acknowledgment is part of your personnel file. The acknowledgment states: our policy formally and clearly states zero tolerance for any form of fraud or misconduct. Every employee plays a key role in maintaining the agency's image and reputation. The acknowledgment also notes that it does not create an employment contract. Annual compliance training and re-acknowledgment are required. The CCO tracks all compliance inquiries, violations, and suggestions. Departments submit annual status reports to the Compliance Committee. All compliance records are maintained for audit and reporting purposes.`,
      contentHtml: `<h3>Compliance Documentation</h3><ul><li>Annual acknowledgment signed by every employee</li><li>Zero tolerance for fraud/misconduct</li><li>Annual training required</li><li>CCO tracks all inquiries and violations</li><li>Records maintained for audit</li></ul>`,
      media: createMedia('Compliance acknowledgment form.', '10-second 720p: Form being signed.', 'image', 'beforeNarration', 'Acknowledgment form.'),
      duration: createDuration('ACHC-ART-M09', 'M09-P07', 'documentation-practice', 'Compliance Documentation', `Annual acknowledgment, training, tracking, records retention.`, 5),
      challenge: { challengeId: 'M09-C06', lessonId: 'M09-P07', moduleId: 'ACHC-ART-M09', title: 'Acknowledgment Understanding', scenario: 'A new employee asks you what the compliance acknowledgment means. She wants to know if signing it means she can be fired for any mistake.', narrationText: 'A new employee is anxious about signing the compliance acknowledgment. What do you explain?', prompt: 'How do you explain the acknowledgment?', interactionType: 'choose-best-response', options: [createChallengeOption('a', 'Explain that the acknowledgment confirms she has been informed about the compliance policy and agrees to follow it. It is about awareness and commitment to ethical conduct, not about punishing honest mistakes. The policy distinguishes between honest errors and intentional misconduct. She should read it carefully and ask the CCO any questions before signing.', 'Correct. The acknowledgment is about awareness and commitment, not punishment for errors. Direct questions to the CCO.', true), createChallengeOption('b', 'Tell her to just sign it without reading it.', 'Employees should understand what they sign. Reading and asking questions is encouraged.', false)], bestPracticeAnswer: 'Explain purpose: awareness and commitment. Not punishment for honest errors. Ask CCO with questions.', teachingPoint: 'The compliance acknowledgment is about commitment to ethical conduct, not fear of honest mistakes.', documentationPrompt: 'No specific documentation needed for this conversation.', escalationPrompt: 'Direct specific compliance questions to the CCO.', estimatedInteractionMinutes: 3, requiredForProgression: true, graded: false, countsTowardFinalScore: false, reviewRequired: false },
      requiredForCompletion: true },
    { pageId: 'M09-P08', moduleId: 'ACHC-ART-M09', pageType: 'documentation-practice', title: 'Corrective Action and Investigation Cooperation',
      narrationText: `When a compliance violation is detected, prompt corrective action is required. The CCO makes recommendations for appropriate action. If corrections are inadequate, the CCO notifies the Compliance Committee or Board. Disciplinary guidelines are established for failing to comply with agency standards and applicable laws. Sanctions parallel other disciplinary policies. If you are asked to cooperate with a compliance investigation, you are obligated to do so honestly and completely. Failure to cooperate may result in disciplinary action. Provide factual information. Do not speculate. Do not withhold relevant information. Do not discuss the investigation with others outside the investigation. The goal of the compliance program is prevention and early detection, not punishment. However, when intentional misconduct is identified, appropriate consequences follow.`,
      contentHtml: `<h3>Corrective Action</h3><ul><li>Prompt corrective action for detected violations</li><li>CCO recommends action; Board if inadequate</li><li>Disciplinary guidelines parallel other policies</li></ul><h3>Investigation Cooperation</h3><ul><li>Obligated to cooperate honestly and completely</li><li>Provide factual information, no speculation</li><li>Do not withhold information</li><li>Do not discuss investigation with others</li></ul>`,
      media: createMedia('Investigation cooperation steps.', '10-second 720p: Steps listed.', 'image', 'beforeNarration', 'Investigation cooperation.'),
      duration: createDuration('ACHC-ART-M09', 'M09-P08', 'documentation-practice', 'Corrective Action', `Corrective action process and investigation cooperation obligations.`, 4),
      challenge: { challengeId: 'M09-C07', lessonId: 'M09-P08', moduleId: 'ACHC-ART-M09', title: 'Investigation Cooperation', scenario: 'You are asked to participate in a compliance investigation about a coworker. The coworker calls you and asks what questions the investigator asked you.', narrationText: 'A coworker under investigation asks what the investigator asked you. What do you do?', prompt: 'How do you respond?', interactionType: 'choose-best-response', options: [createChallengeOption('a', 'Do not share details of the investigation with the coworker. Explain that you are not able to discuss the investigation. Investigations are confidential. Sharing information could compromise the process and may be considered obstruction or failure to cooperate.', 'Correct. Investigations are confidential. Do not share details with anyone outside the investigation.', true), createChallengeOption('b', 'Tell them everything since they have a right to know.', 'Individuals under investigation have certain rights, but those do not include knowing what witnesses said. Confidentiality protects the integrity of the process.', false)], bestPracticeAnswer: 'Do not share investigation details. Explain you cannot discuss it.', teachingPoint: 'Investigation confidentiality is critical. Sharing details can compromise the investigation and may have consequences for you.', documentationPrompt: 'No documentation of the conversation is required unless the coworker attempts to influence your testimony.', escalationPrompt: 'If the coworker pressures you or attempts to influence your statements, report to the CCO or investigator.', estimatedInteractionMinutes: 3, requiredForProgression: true, graded: false, countsTowardFinalScore: false, reviewRequired: false },
