        { questionId: 'M09-PRE-Q04', moduleId: 'ACHC-ART-M09', questionText: 'If you suspect fraud, you should:', options: [createOption('a', 'Investigate yourself', false, 'Report to CCO; investigation is not your role.'), createOption('b', 'Report to the CCO through compliance channels', true, 'Correct.'), createOption('c', 'Ignore it', false, 'Failure to report is a compliance violation.'), createOption('d', 'Post about it online', false, 'Public disclosure is inappropriate.')], mappedObjective: 'Apply reporting obligations', source: 'supplemental', reviewRequired: false },
        { questionId: 'M09-PRE-Q05', moduleId: 'ACHC-ART-M09', questionText: 'Whistleblower protections mean:', options: [createOption('a', 'You can never be fired', false, 'Protection is against retaliation for reporting, not absolute job protection.'), createOption('b', 'You cannot be retaliated against for reporting in good faith', true, 'Correct.'), createOption('c', 'You get a bonus for reporting', false, 'No bonus is provided.'), createOption('d', 'Your report is published publicly', false, 'Reports are investigated confidentially.')], mappedObjective: 'Identify whistleblower protections', source: 'supplemental', reviewRequired: false },
