        { questionId: 'M09-FIN-Q01', moduleId: 'ACHC-ART-M09', questionText: 'A Corporate Compliance program is a system which is designed to detect and prevent violations of law by the agents, employees, officers and directors of a business.', options: [createOption('a', 'True', true, 'Correct.'), createOption('b', 'False', false, 'This is the exact definition.')], mappedObjective: 'Define compliance', source: 'provided', reviewRequired: false },
