        { questionId: 'M09-FIN-Q03', moduleId: 'ACHC-ART-M09', questionText: 'The CCO (Corporate Compliance Officer) is:', options: [createOption('a', 'The Administrator or designee', true, 'Correct.'), createOption('b', 'The newest employee', false, 'CCO is a senior role.'), createOption('c', 'An outside consultant', false, 'CCO is internal.'), createOption('d', 'Automatically the DON', false, 'The Administrator, not DON.')], mappedObjective: 'Identify CCO', source: 'supplemental', reviewRequired: false },
