        { questionId: 'M09-FIN-Q06', moduleId: 'ACHC-ART-M09', questionText: 'Employees can report fraud to the OIG and are protected under:', options: [createOption('a', 'HIPAA', false, 'HIPAA covers privacy, not whistleblower protection.'), createOption('b', 'The Whistleblower Protection Act', true, 'Correct.'), createOption('c', 'The ADA', false, 'ADA covers disabilities.'), createOption('d', 'Nothing ΓÇö there is no protection', false, 'Whistleblower protections exist.')], mappedObjective: 'Identify whistleblower protections', source: 'supplemental', reviewRequired: false },
        { questionId: 'M09-FIN-Q07', moduleId: 'ACHC-ART-M09', questionText: 'The agency shall not hire individuals who have been:', options: [createOption('a', 'Over 65 years old', false, 'Age discrimination is prohibited.'), createOption('b', 'Sanctioned or excluded by federal health programs', true, 'Correct. Excluded individuals cannot be hired or contracted.'), createOption('c', 'Employees of other agencies', false, 'Previous employment does not disqualify.'), createOption('d', 'Non-English speakers', false, 'Language is not a disqualifying factor.')], mappedObjective: 'Identify exclusion screening', source: 'supplemental', reviewRequired: false },
        { questionId: 'M09-FIN-Q08', moduleId: 'ACHC-ART-M09', questionText: 'Non-retaliation for compliance reporting means:', options: [createOption('a', 'Employees can file false reports without consequences', false, 'Reports must be in good faith. False reports have consequences.'), createOption('b', 'Employees will not face adverse action for good-faith compliance reporting', true, 'Correct.'), createOption('c', 'Only managers are protected', false, 'All employees are protected.'), createOption('d', 'Protection expires after 30 days', false, 'Protection does not expire.')], mappedObjective: 'Apply non-retaliation', source: 'supplemental', reviewRequired: false },
        { questionId: 'M09-FIN-Q09', moduleId: 'ACHC-ART-M09', questionText: 'If you are asked to cooperate with a compliance investigation, you should:', options: [createOption('a', 'Refuse to participate', false, 'Cooperation is obligatory.'), createOption('b', 'Provide factual information honestly and completely, without discussing the investigation with others', true, 'Correct.'), createOption('c', 'Share the investigation details with colleagues', false, 'Investigations are confidential.'), createOption('d', 'Speculate about what you think happened', false, 'Provide facts, not speculation.')], mappedObjective: 'Apply investigation cooperation', source: 'supplemental', reviewRequired: false },
        { questionId: 'M09-FIN-Q10', moduleId: 'ACHC-ART-M09', questionText: 'Vendor gifts tied to product recommendations should be:', options: [createOption('a', 'Accepted gracefully', false, 'These may constitute kickbacks.'), createOption('b', 'Declined and reported to the CCO', true, 'Correct.'), createOption('c', 'Shared with the team', false, 'Sharing does not resolve the compliance issue.'), createOption('d', 'Accepted if under $50', false, 'Vendor gifts tied to recommendations are problematic regardless of value.')], mappedObjective: 'Apply gifts/kickback rules', source: 'supplemental', reviewRequired: false },
        { questionId: 'M09-FIN-Q11', moduleId: 'ACHC-ART-M09', questionText: 'Documentation integrity requires:', options: [createOption('a', 'Documenting actual services provided accurately', true, 'Correct.'), createOption('b', 'Rounding up visit times to meet billing requirements', false, 'Rounding up falsifies records.'), createOption('c', 'Documenting what the supervisor tells you to write', false, 'Your documentation must be accurate regardless of instructions.'), createOption('d', 'Copying previous visit notes for efficiency', false, 'Each visit requires original, accurate documentation.')], mappedObjective: 'Apply documentation integrity', source: 'supplemental', reviewRequired: false },
