    { pageId: 'M09-P13', moduleId: 'ACHC-ART-M09', pageType: 'remediation', title: 'Remediation: Corporate Compliance', narrationText: `Review: Compliance program detects and prevents law violations. CCO is Administrator. Board has ultimate responsibility. Penalties: prison, fines, sanctions, probation. Zero tolerance for fraud. Accurate documentation required. No kickbacks or gifts from vendors. Report to CCO or Board. Whistleblower protection. Non-retaliation. Cooperate with investigations. Annual acknowledgment and training. Retake after review.`, contentHtml: `<h3>Remediation</h3>`, media: createMedia('Study.', '10-second 720p: Review.', 'image', 'beforeNarration', 'Remediation.'), duration: createDuration('ACHC-ART-M09', 'M09-P13', 'remediation', 'Remediation', `Review.`, 5), requiredForCompletion: true },
