const MODULE_M10: ModuleData = {
  moduleId: 'ACHC-ART-M10', title: 'Ethics in Healthcare',
  description: 'Ethical principles, boundaries, conflicts, gifts, confidentiality, informed decision-making, capacity, refusal, end-of-life, professional conduct, escalation, documentation.',
  version: '1.0.0', sourceRefs: ['ACHC Training Document ΓÇö Ethics Section'],
  policyRefs: ['CL-PR-001 (Patient Rights & Responsibilities)'], formRefs: ['Ethics Committee Referral'],
  workflowRefs: ['Ethics Committee Workflow'], reviewRequired: false,
  pages: [
    { pageId: 'M10-P01', moduleId: 'ACHC-ART-M10', pageType: 'overview', title: 'Ethics in Healthcare ΓÇö Overview', narrationText: `Welcome to Module Ten: Ethics in Healthcare. Healthcare ethics involves making well-researched and considerate decisions about medical treatments while respecting patient beliefs and wishes. Your agency has a written Code of Ethics covering patient rights, relationships with other providers, fiscal responsibilities, marketing, and personnel. The Ethics Committee assists staff, patients, and families with difficult ethical decisions. Ethical issues you may encounter include confidentiality, boundaries, informed consent, patient capacity, refusal of treatment, advance directives, end-of-life decisions, discrimination, relationships with patients, conflicts between personal beliefs and patient care, and situations where illegal activity jeopardizes safety. The agency policy recognizes that ethical issues may develop and provides a framework for resolution through the Ad Hoc Ethics Committee of the Professional Advisory Committee. Staff personal values that conflict with care obligations are accommodated through reassignment without disrupting patient care. Eighty percent passing required.`, contentHtml: `<h2>Module 10: Ethics</h2>`, media: createMedia('Ethics balance scale.', '10-second 720p: Balance scale. "Module 10."', 'image', 'beforeNarration', 'Ethics overview.'), duration: createDuration('ACHC-ART-M10', 'M10-P01', 'overview', 'Overview', `Ethics overview.`, 1), requiredForCompletion: true },
    { pageId: 'M10-P02', moduleId: 'ACHC-ART-M10', pageType: 'instruction', title: 'Ethical Principles and the Code of Ethics', narrationText: `The Code of Ethics guides the agency in patient rights, provider relationships, fiscal responsibilities, marketing, and personnel. Key ethical principles include patient autonomy, which means patients make their own informed decisions; beneficence, meaning acting in the patient's best interest; non-maleficence, meaning do no harm; justice, meaning fair and equal treatment; confidentiality, protecting patient information; honesty, providing truthful information; and professional boundaries, maintaining appropriate relationships. The Ethics Committee meets when ethical issues arise. Anyone may initiate consideration by notifying the Administrator or Director. Minutes are kept and results communicated appropriately. Ethical issues for patients include DNR conflicts among family members, cultural or religious healing practices that concern the worker, physicians concealing information from patients, physician non-response to care requests, patient refusal of services the worker believes are necessary, and illegal activity in the home jeopardizing safety. For employees, ethical issues include religious holidays, right-to-life concerns, administering blood transfusions, respecting decisions not to seek medical care for religious reasons, and termination of life support decisions.`, contentHtml: `<h3>Ethical Principles</h3><ul><li>Autonomy, beneficence, non-maleficence, justice</li><li>Confidentiality, honesty, professional boundaries</li></ul><h3>Code of Ethics Areas</h3><p>Patient rights, provider relationships, fiscal, marketing, personnel</p><h3>Ethics Committee</h3><p>Ad Hoc ΓÇö convened when issues arise. Anyone may initiate.</p>`, media: createMedia('Ethical principles wheel.', '10-second 720p: Principles appear.', 'image', 'duringNarration', 'Ethical principles.'), duration: createDuration('ACHC-ART-M10', 'M10-P02', 'instruction', 'Ethical Principles', `Ethical principles and Code of Ethics overview.`, 2), challenge: { challengeId: 'M10-C01', lessonId: 'M10-P02', moduleId: 'ACHC-ART-M10', title: 'Ethical Dilemma', scenario: 'A patient\'s family asks you not to tell the patient about his terminal diagnosis. The physician has agreed not to disclose. You believe the patient has a right to know.', narrationText: 'Family and physician are concealing a terminal diagnosis. You believe the patient should know. What do you do?', prompt: 'How do you handle this ethical conflict?', interactionType: 'scenario-decision', options: [createChallengeOption('a', 'Report the ethical concern to your supervisor and request an Ethics Committee review. Do not disclose the diagnosis yourself ΓÇö that is the physician\'s responsibility. The Ethics Committee can address the conflict between the patient\'s right to information and the family/physician\'s decision. Document your concern.', 'Correct. This is an Ethics Committee referral situation. You advocate for the patient through proper channels without overstepping your scope.', true), createChallengeOption('b', 'Tell the patient yourself since they have a right to know.', 'While the patient has rights, disclosure of a diagnosis is the physician\'s responsibility. Use proper escalation channels.', false), createChallengeOption('c', 'Do nothing since the physician agreed.', 'You have a professional obligation to advocate for the patient through proper channels when you believe their rights are compromised.', false)], bestPracticeAnswer: 'Ethics Committee referral through supervisor. Do not disclose yourself. Document.', teachingPoint: 'When ethical conflicts arise between patient rights and family/physician decisions, escalate to the Ethics Committee through proper channels.', documentationPrompt: 'Document your ethical concern and escalation to supervisor for Ethics Committee review.', escalationPrompt: 'Notify Administrator/Director for Ethics Committee convening.', estimatedInteractionMinutes: 5, requiredForProgression: true, graded: false, countsTowardFinalScore: false, reviewRequired: false }, requiredForCompletion: true },
    // M10 remaining pages follow identical pattern: instruction with challenges, scenario, doc practice, pre-assess, final, remediation, attestation, certificate
    { pageId: 'M10-P03', moduleId: 'ACHC-ART-M10', pageType: 'instruction', title: 'Boundaries and Professional Conduct', narrationText: `Professional boundaries protect both patients and healthcare workers. Relationships with patients, particularly sexual relationships, are forbidden by medical and nursing codes of ethics. Such actions constitute serious misconduct resulting in expulsion from the profession and loss of license. Patients are dependent and vulnerable, making any sexual relationship an abuse of power. Boundary violations also include accepting large gifts, conducting personal business during visits, sharing excessive personal information, becoming emotionally over-involved, and socializing with patients outside of professional duties. Maintain professional conduct at all times. Your role is to provide care, not to become a friend, financial advisor, or confidant beyond the therapeutic relationship. If you feel boundaries are becoming blurred, discuss with your supervisor. Malpractice risk exists for all practitioners ΓÇö care that is omitted, deliberate harm, defective equipment, or actions outside your scope can result in lawsuits.`, contentHtml: `<h3>Professional Boundaries</h3><ul><li>No sexual relationships with patients ΓÇö ever</li><li>No large gifts, no personal business during visits</li><li>Limit personal sharing</li><li>No socializing outside professional role</li><li>Discuss boundary concerns with supervisor</li></ul>`, media: createMedia('Boundary line illustration.', '10-second 720p: Professional boundary.', 'image', 'beforeNarration', 'Boundaries.'), duration: createDuration('ACHC-ART-M10', 'M10-P03', 'instruction', 'Boundaries', `Professional boundaries and conduct.`, 2), challenge: { challengeId: 'M10-C02', lessonId: 'M10-P03', moduleId: 'ACHC-ART-M10', title: 'Boundary Scenario', scenario: 'A lonely elderly patient asks you to stay longer and have dinner with her. She says you are her only visitor.', narrationText: 'A lonely patient wants you to stay for dinner. How do you maintain boundaries compassionately?', prompt: 'What is the professional response?', interactionType: 'choose-best-response', options: [createChallengeOption('a', 'Compassionately decline, explaining your professional role. Acknowledge her feelings of loneliness. Offer to help connect her with social services, community resources, or companion programs. Document the isolation concern and notify your supervisor for care plan consideration.', 'Correct. Compassionate boundary maintenance while advocating for the patient\'s social needs through appropriate channels.', true), createChallengeOption('b', 'Stay for dinner since she is lonely.', 'While compassionate, this crosses professional boundaries and sets unsustainable expectations.', false)], bestPracticeAnswer: 'Compassionate decline, acknowledge feelings, connect with resources, document isolation.', teachingPoint: 'Boundaries can be maintained with compassion. Address underlying needs through appropriate resources.', documentationPrompt: 'Document social isolation concern, resources offered, supervisor notified.', escalationPrompt: 'Notify supervisor for social service referral consideration.', estimatedInteractionMinutes: 4, requiredForProgression: true, graded: false, countsTowardFinalScore: false, reviewRequired: false }, requiredForCompletion: true },
    { pageId: 'M10-P04', moduleId: 'ACHC-ART-M10', pageType: 'instruction', title: 'Confidentiality, Consent, and End-of-Life Ethics', narrationText: `Confidentiality is both an ethical and legal obligation under HIPAA. Keeping information confidential shows respect for patient autonomy. However, if there is risk to a third party, an ethical professional may need to break confidentiality to prevent harm. Informed consent requires that patients understand what is being proposed before agreeing. Surgery without proper consent is generally considered assault. When treating adolescents, potential conflicts arise between parental involvement and minor consent laws which vary by state. Discrimination based on race, gender, color, or religion is a serious ethical issue that must be addressed immediately if observed. Honesty is fundamental ΓÇö diagnostic results must be shared with patients and families. False hopes and false reassurances are discouraged. End-of-life decisions are among the most challenging ethical situations. Elderly or terminally ill patients may have specific wishes for their care. A living will can prevent confusion. When ethical conflicts arise about end-of-life care, the Ethics Committee should be involved. Your role is to document patient wishes, honor advance directives, advocate for the patient through proper channels, and seek Ethics Committee guidance when conflicts arise.`, contentHtml: `<h3>Confidentiality Ethics</h3><p>Respect autonomy; break only to prevent harm to third parties</p><h3>Consent</h3><p>Informed understanding required; minor consent laws vary by state</p><h3>End-of-Life</h3><ul><li>Honor advance directives</li><li>Ethics Committee for conflicts</li><li>Document patient wishes</li><li>No false hopes or reassurances</li></ul>`, media: createMedia('Ethical decision framework.', '10-second 720p: Decision points.', 'image', 'beforeNarration', 'Ethics framework.'), duration: createDuration('ACHC-ART-M10', 'M10-P04', 'instruction', 'Confidentiality and End-of-Life', `Confidentiality, consent, end-of-life ethical considerations.`, 2), challenge: { challengeId: 'M10-C03', lessonId: 'M10-P04', moduleId: 'ACHC-ART-M10', title: 'End-of-Life Ethics', scenario: 'A terminally ill patient has a DNR but her son is demanding full resuscitation if she stops breathing. The patient is alert and reaffirms she wants the DNR honored.', narrationText: 'Son demands resuscitation against patient\'s DNR. Patient is competent and reaffirms DNR. What do you do?', prompt: 'Whose wishes prevail?', interactionType: 'scenario-decision', options: [createChallengeOption('a', 'The competent patient\'s wishes prevail. Document that the patient reaffirmed the DNR. Notify the physician and supervisor about the family conflict. Request Ethics Committee involvement if needed. Support the patient\'s autonomy while being compassionate to the son\'s distress.', 'Correct. A competent patient\'s advance directive takes precedence over family wishes. Document, notify, and involve Ethics Committee if needed.', true), createChallengeOption('b', 'Honor the son\'s wishes since he is family.', 'A competent patient\'s own wishes take legal and ethical precedence over family wishes.', false)], bestPracticeAnswer: 'Patient\'s DNR prevails. Document reaffirmation. Notify physician. Ethics Committee if needed.', teachingPoint: 'Competent patients control their own advance directive decisions. Family conflict requires documentation, notification, and potential Ethics Committee involvement.', documentationPrompt: 'Document: patient reaffirmed DNR, son\'s request documented, physician notified, Ethics Committee referral if conflict continues.', escalationPrompt: 'Notify physician and supervisor. Ethics Committee if family conflict persists.', estimatedInteractionMinutes: 5, requiredForProgression: true, graded: false, countsTowardFinalScore: false, reviewRequired: false }, requiredForCompletion: true },
    { pageId: 'M10-P05', moduleId: 'ACHC-ART-M10', pageType: 'instruction', title: 'Employee Ethical Conflicts and Resolution', narrationText: `The agency recognizes that staff personal values and beliefs sometimes conflict with care obligations. Such issues include working on religious holidays, right-to-life issues, administering blood transfusions, respecting patients\' religious decisions to forgo medical care, ethnic and sexual orientation issues, and end-of-life decisions. CL-PR-001 (Patient Rights & Responsibilities) states that refusal based on personal values will not disrupt patient care. An alternative method of care will be arranged. Performance evaluations will appropriately consider motives related to cultural or religious refusal. If you face an ethical conflict between your beliefs and patient care, notify your supervisor. Do not provide compromised care. The agency will reassign without disrupting the patient. This is not a weakness ΓÇö it is professional self-awareness that protects both you and the patient.`, contentHtml: `<h3>Employee Ethical Conflicts</h3><ul><li>Religious holidays, right-to-life, blood transfusions</li><li>Religious decisions to forgo care</li><li>Sexual orientation care issues</li><li>End-of-life participation</li></ul><h3>Resolution</h3><ul><li>Notify supervisor ΓÇö do not provide compromised care</li><li>Alternative care arranged</li><li>Patient care is not disrupted</li><li>Evaluations consider cultural/religious motives</li></ul>`, media: createMedia('Balance between personal beliefs and professional duty.', '10-second 720p: Balance scale.', 'image', 'beforeNarration', 'Employee ethics.'), duration: createDuration('ACHC-ART-M10', 'M10-P05', 'instruction', 'Employee Ethics', `Employee ethical conflicts and resolution process.`, 2), challenge: { challengeId: 'M10-C04', lessonId: 'M10-P05', moduleId: 'ACHC-ART-M10', title: 'Personal Conflict', scenario: 'You are assigned to a patient whose lifestyle conflicts with your deeply held religious beliefs. You feel you cannot provide care without judgment.', narrationText: 'Your religious beliefs conflict with a patient\'s lifestyle. How do you handle this?', prompt: 'What is the professional approach?', interactionType: 'scenario-decision', options: [createChallengeOption('a', 'Notify your supervisor that your personal beliefs may affect care quality for this patient. Request reassignment. The agency will arrange alternative care without disrupting the patient\'s services. This is not a failure ΓÇö it is professional self-awareness.', 'Correct. Self-awareness and honest communication with your supervisor protects both you and the patient.', true), createChallengeOption('b', 'Provide care but let the patient know you disapprove of their lifestyle.', 'Expressing disapproval violates the patient\'s right to non-discriminatory, respectful care.', false), createChallengeOption('c', 'Refuse to see the patient and walk away.', 'Walking away without notification disrupts care. Proper notification allows smooth reassignment.', false)], bestPracticeAnswer: 'Notify supervisor, request reassignment, agency arranges alternative without disrupting care.', teachingPoint: 'Professional self-awareness about personal limitations protects patients. Supervisor notification enables proper accommodation.', documentationPrompt: 'No patient chart documentation needed for reassignment requests. Handle through supervisor/HR.', escalationPrompt: 'Supervisor handles reassignment. Patient care must not be disrupted.', estimatedInteractionMinutes: 4, requiredForProgression: true, graded: false, countsTowardFinalScore: false, reviewRequired: false }, requiredForCompletion: true },
    // M10 scenario, doc practice, pre-assess, final, remediation, attestation, certificate pages
    { pageId: 'M10-P06', moduleId: 'ACHC-ART-M10', pageType: 'scenario-challenge', title: 'Ethics Scenario: Unsafe Home Activity', narrationText: `You visit a patient and observe what appears to be drug paraphernalia and illegal activity in the home. Your patient needs daily wound care and lives with the individuals involved. You feel unsafe but the patient needs your care. This involves multiple ethical considerations: your safety, patient abandonment concerns, mandatory reporting obligations, and continuing care obligations. Apply your ethics training to determine the correct response.`, contentHtml: `<h3>Scenario: Illegal Activity in Patient Home</h3>`, media: createMedia('Home safety concern illustration.', '10-second 720p: Safety concern.', 'image', 'beforeNarration', 'Ethics scenario.'), duration: createDuration('ACHC-ART-M10', 'M10-P06', 'scenario-challenge', 'Ethics Scenario', `Unsafe home with illegal activity.`, 5), challenge: { challengeId: 'M10-C05', lessonId: 'M10-P06', moduleId: 'ACHC-ART-M10', title: 'Unsafe Activity Response', scenario: 'Drug activity in patient home. Patient needs care. You feel unsafe.', narrationText: 'How do you balance safety, patient care, and reporting obligations?', prompt: 'What is the correct ethical response?', interactionType: 'field-safety-decision', options: [createChallengeOption('a', 'If you feel immediately unsafe, withdraw from the home. Report to your supervisor immediately. Document what you observed objectively. The agency will coordinate a safety plan ΓÇö which may include scheduling visits when the unsafe individuals are absent, requesting a companion for visits, or involving law enforcement if patient safety is at risk. Patient care continues through a modified approach, not abandonment.', 'Correct. Safety first, then report, document, and coordinate a modified care plan. This is not abandonment ΓÇö it is safe care planning.', true), createChallengeOption('b', 'Ignore the activity and provide care normally.', 'Ignoring unsafe conditions puts you at risk and fails to address potential patient safety concerns.', false), createChallengeOption('c', 'Discharge the patient immediately.', 'Unilateral discharge is not your decision. The agency coordinates modified care plans.', false)], bestPracticeAnswer: 'Withdraw if unsafe, report, document, agency coordinates modified care plan.', teachingPoint: 'Illegal activity in patient homes is an agency ethics policy issue. Your safety comes first, but patient care continues through modified approaches.', documentationPrompt: 'Document: observations (objective), your actions, supervisor notification, safety concern.', escalationPrompt: 'Notify supervisor immediately. May involve law enforcement and Adult Protective Services.', estimatedInteractionMinutes: 5, requiredForProgression: true, graded: false, countsTowardFinalScore: false, reviewRequired: false }, requiredForCompletion: true },
    { pageId: 'M10-P07', moduleId: 'ACHC-ART-M10', pageType: 'documentation-practice', title: 'Ethics Documentation Practice', narrationText: `Ethical situations require careful documentation. Document the ethical issue identified, who was involved, what actions you took, who you notified, and the outcome or plan. For Ethics Committee referrals, document your concern and that you initiated the referral. Minutes of Ethics Committee meetings are maintained and results communicated to appropriate parties. Never document your personal opinions about a patient's lifestyle, beliefs, or choices ΓÇö document facts and clinical observations only.`, contentHtml: `<h3>Ethics Documentation</h3><ul><li>Issue identified, persons involved, actions taken, notifications, outcome/plan</li><li>Ethics Committee referral documented</li><li>Facts only ΓÇö no personal opinions about lifestyle/beliefs</li></ul>`, media: createMedia('Documentation template.', '10-second 720p: Template.', 'image', 'beforeNarration', 'Documentation.'), duration: createDuration('ACHC-ART-M10', 'M10-P07', 'documentation-practice', 'Ethics Documentation', `Document ethics events factually.`, 5), challenge: { challengeId: 'M10-C06', lessonId: 'M10-P07', moduleId: 'ACHC-ART-M10', title: 'Ethics Documentation', scenario: 'Document the DNR conflict scenario.', narrationText: 'Select best documentation for the DNR family conflict.', prompt: 'Best documentation?', interactionType: 'documentation-practice', options: [createChallengeOption('a', '"Family fight about DNR."', 'Vague, judgmental, missing details.', false), createChallengeOption('b', '"Patient [name], alert and oriented, reaffirmed desire for DNR to remain in effect. Son [name] expressed disagreement and requested full resuscitation if needed. Patient\'s competent wishes take precedence per advance directive policy. Physician Dr. [name] notified at [time] of family conflict. Supervisor notified. Ethics Committee referral initiated if conflict continues. Patient\'s emotional state noted as [calm/distressed]. Son offered supportive conversation and referral to social services."', 'Correct. Factual, complete, respectful to all parties.', true)], bestPracticeAnswer: 'Complete factual documentation respecting all parties.', teachingPoint: 'Ethics documentation is factual, non-judgmental, and respectful.', documentationPrompt: 'Template: issue, persons, patient wishes, notifications, plan.', escalationPrompt: 'Ethics Committee if needed.', estimatedInteractionMinutes: 5, requiredForProgression: true, graded: false, countsTowardFinalScore: false, reviewRequired: false }, requiredForCompletion: true },
    { pageId: 'M10-P08', moduleId: 'ACHC-ART-M10', pageType: 'documentation-practice', title: 'Ethical Decision-Making Framework', narrationText: `When facing an ethical dilemma, use this framework: First, identify the ethical issue. Second, gather relevant facts and understand the clinical situation. Third, identify the stakeholders and their perspectives ΓÇö patient, family, healthcare team. Fourth, consider the ethical principles at play ΓÇö autonomy, beneficence, non-maleficence, justice. Fifth, identify possible courses of action. Sixth, evaluate each option against ethical principles and agency policy. Seventh, make a decision or escalate to the Ethics Committee. Eighth, act on the decision. Ninth, document and evaluate the outcome. This framework does not always give easy answers, but it ensures thorough, principled consideration of difficult situations.`, contentHtml: `<h3>Ethical Decision Framework</h3><ol><li>Identify the ethical issue</li><li>Gather facts</li><li>Identify stakeholders and perspectives</li><li>Consider ethical principles</li><li>Identify possible actions</li><li>Evaluate options against principles/policy</li><li>Decide or escalate to Ethics Committee</li><li>Act</li><li>Document and evaluate</li></ol>`, media: createMedia('Decision framework steps.', '10-second 720p: Steps listed.', 'image', 'beforeNarration', 'Decision framework.'), duration: createDuration('ACHC-ART-M10', 'M10-P08', 'documentation-practice', 'Decision Framework', `Nine-step ethical decision-making framework.`, 4), challenge: { challengeId: 'M10-C07', lessonId: 'M10-P08', moduleId: 'ACHC-ART-M10', title: 'Framework Application', scenario: 'Apply the framework to the drug activity scenario.', narrationText: 'Apply the ethical decision framework to the home drug activity situation.', prompt: 'What principles are most relevant?', interactionType: 'identify-the-risk', options: [createChallengeOption('a', 'Non-maleficence (do no harm to yourself or patient), beneficence (continue needed care), justice (patient deserves care regardless of household), and autonomy (patient\'s right to receive care in their home). Balance leads to: withdraw if unsafe, coordinate modified care plan, do not abandon the patient.', 'Correct. Multiple principles apply and must be balanced.', true), createChallengeOption('b', 'Only patient autonomy matters.', 'All principles must be balanced, including worker safety.', false)], bestPracticeAnswer: 'Balance all principles: non-maleficence, beneficence, justice, autonomy.', teachingPoint: 'Ethical decisions rarely involve only one principle. Thoughtful balancing of competing principles leads to better outcomes.', documentationPrompt: 'Document your ethical reasoning when making complex decisions.', escalationPrompt: 'Ethics Committee for complex situations.', estimatedInteractionMinutes: 4, requiredForProgression: true, graded: false, countsTowardFinalScore: false, reviewRequired: false }, requiredForCompletion: true },
