      { questionId: 'M10-PRE-Q01', moduleId: 'ACHC-ART-M10', questionText: 'The Code of Ethics serves as a guideline in:', options: [createOption('a', 'Patient rights only', false, 'The Code covers multiple areas.'), createOption('b', 'Patient rights, provider relationships, fiscal responsibilities, marketing, and personnel ΓÇö all of the above', true, 'Correct.'), createOption('c', 'Marketing only', false, 'One of five areas.'), createOption('d', 'Personnel only', false, 'One of five areas.')], mappedObjective: 'Identify Code of Ethics scope', source: 'provided', reviewRequired: false },
