      { questionId: 'M10-PRE-Q05', moduleId: 'ACHC-ART-M10', questionText: 'A competent patient\'s advance directive takes precedence over:', options: [createOption('a', 'Family wishes', true, 'Correct. Competent patient\'s own wishes prevail.'), createOption('b', 'Nothing', false, 'The directive does take precedence.'), createOption('c', 'All laws', false, 'The directive works within the legal framework.'), createOption('d', 'Agency policy', false, 'Agency policy honors the directive.')], mappedObjective: 'Apply advance directive ethics', source: 'supplemental', reviewRequired: false },
