      { questionId: 'M10-FIN-Q06', moduleId: 'ACHC-ART-M10', questionText: 'The Ethics Committee can be initiated by:', options: [createOption('a', 'Only the physician', false, 'Anyone may initiate.'), createOption('b', 'Only the Administrator', false, 'Anyone.'), createOption('c', 'Anyone by notifying the Administrator or Director', true, 'Correct.'), createOption('d', 'No one ΓÇö it meets automatically', false, 'It is convened when issues arise, initiated by anyone.')], mappedObjective: 'Identify Ethics Committee access', source: 'supplemental', reviewRequired: false },
