    { pageId: 'M10-P13', moduleId: 'ACHC-ART-M10', pageType: 'remediation', title: 'Remediation: Ethics', narrationText: `Review: Code of Ethics covers five areas. Professional boundaries: no sexual relationships, maintain professional distance. Personal conflicts: notify supervisor for reassignment. Ethics Committee: anyone can initiate. Competent patient wishes prevail over family for advance directives. Confidentiality breakable only to prevent third-party harm. No false hopes. Illegal activity: withdraw if unsafe, coordinate modified care. Discrimination: addressed immediately. Retake after review.`, contentHtml: `<h3>Remediation</h3>`, media: createMedia('Study.', '10-second 720p: Review.', 'image', 'beforeNarration', 'Remediation.'), duration: createDuration('ACHC-ART-M10', 'M10-P13', 'remediation', 'Remediation', `Review.`, 5), requiredForCompletion: true },
