  pages: [
    { pageId: 'M11-P01', moduleId: 'ACHC-ART-M11', pageType: 'overview', title: 'TB & Bloodborne Pathogens ΓÇö Overview', narrationText: `Welcome to Module Eleven: TB and Bloodborne Pathogens. Bloodborne pathogens are infectious microorganisms in human blood that cause disease ΓÇö primarily hepatitis B, hepatitis C, and HIV. They spread through direct contact, indirect contact, respiratory droplets, and vector-borne transmission. TB is an airborne disease with specific precautions. Your agency adheres to OSHA standards for bloodborne pathogen protection and CDC guidelines for TB infection control. OSHA requires employers to have an exposure control plan, provide hepatitis B vaccination within ten working days of initial assignment, and provide PPE. This module covers transmission routes, standard precautions application, BBP exposure response, needlestick protocols, TB signs and risk indicators, airborne precautions, N95 respirator requirements, field response protocols, post-exposure reporting and medical follow-up, TB testing requirements, and documentation and confidentiality. Eighty percent passing required.`, contentHtml: `<h2>Module 11: TB & Bloodborne Pathogens</h2>`, media: createMedia('BBP prevention equipment.', '10-second 720p: PPE and biohazard symbols. "Module 11."', 'image', 'beforeNarration', 'TB/BBP overview.'), duration: createDuration('ACHC-ART-M11', 'M11-P01', 'overview', 'Overview', `TB and BBP overview.`, 1), requiredForCompletion: true },
