    { pageId: 'M11-P02', moduleId: 'ACHC-ART-M11', pageType: 'instruction', title: 'Bloodborne Pathogen Transmission and Prevention', narrationText: `Bloodborne pathogens spread through direct contact when infected blood enters another person's body, indirect contact when skin touches contaminated objects, respiratory droplet transmission, and vector-borne transmission. The primary BBPs of concern are hepatitis B, hepatitis C, and HIV. Standard precautions are your primary defense ΓÇö treat all blood and body fluids as infectious. OSHA requires employers to implement an exposure control plan with engineering controls as the primary means of protection, including needleless devices and shielded needles. PPE requirements include gloves, masks, eyewear, and gowns when exposure is anticipated. Cover cuts and sores before gloving. Change gloves between patients. Wash hands immediately after care. Use biohazard bags for contaminated materials. Clean with one-to-ten bleach solution. OSHA requires the hepatitis B vaccination series to be made available to all employees with occupational exposure within ten working days of initial assignment. Employees may decline but must be offered the vaccination later if they change their mind.`, contentHtml: `<h3>BBP Transmission</h3><ul><li>Direct, indirect, respiratory droplet, vector-borne</li><li>Primary: HBV, HCV, HIV</li></ul><h3>Prevention</h3><ul><li>Standard precautions ΓÇö treat all as infectious</li><li>Engineering controls (needleless devices)</li><li>PPE: gloves, masks, eyewear, gowns</li><li>Hep B vaccine within 10 working days</li><li>1:10 bleach for cleanup</li></ul>`, media: createMedia('BBP transmission routes infographic.', '10-second 720p: Transmission routes shown.', 'image', 'duringNarration', 'Transmission.'), duration: createDuration('ACHC-ART-M11', 'M11-P02', 'instruction', 'BBP Transmission', `BBP transmission and prevention.`, 2), challenge: { challengeId: 'M11-C01', lessonId: 'M11-P02', moduleId: 'ACHC-ART-M11', title: 'BBP Prevention', scenario: 'A new employee says she declined the Hep B vaccine at hire but now wants it after a close call with a needlestick.', narrationText: 'An employee who declined the Hep B vaccine now wants it. Is it still available?', prompt: 'Can she still get the vaccine?', interactionType: 'choose-best-response', options: [createChallengeOption('a', 'Yes. OSHA requires the employer to make the vaccination available if the employee later decides to accept it. Contact the office to arrange vaccination.', 'Correct. The employer must make the vaccination available at any time if the employee changes their mind.', true), createChallengeOption('b', 'No, she missed her chance.', 'OSHA requires the vaccine to remain available.', false)], bestPracticeAnswer: 'Yes, the employer must provide it if she changes her mind.', teachingPoint: 'Hep B vaccination must remain available to employees who initially decline.', documentationPrompt: 'Document vaccination request and arrange through the office.', escalationPrompt: 'Contact office for vaccination scheduling.', estimatedInteractionMinutes: 3, requiredForProgression: true, graded: false, countsTowardFinalScore: false, reviewRequired: false }, requiredForCompletion: true },
