  pages: [
    { pageId: 'M12-P01', moduleId: 'ACHC-ART-M12', pageType: 'overview', title: 'Medical Device Act ΓÇö Overview', narrationText: `Welcome to Module Twelve: Medical Device Act. Each year the FDA receives hundreds of thousands of medical device reports of suspected device-associated deaths, serious injuries, and malfunctions. Medical Device Reporting is a post-market surveillance tool the FDA uses to monitor device performance and detect safety issues. As a home health field worker, you use and monitor medical devices in patient homes daily. You are often the first to notice a device malfunction or adverse event. Your ability to recognize, respond to, report, and document device events protects patients and supports the agency's regulatory compliance. This module covers mandatory and voluntary reporting requirements, reportable event definitions including death, serious injury, and malfunction, the reporting chain from field worker to Administrator to FDA, the ten-day reporting timeline, Form 3500A requirements, device preservation and evidence retention, near-miss handling, QAPI escalation, and annual reporting requirements. Eighty percent passing required.`, contentHtml: `<h2>Module 12: Medical Device Act</h2>`, media: createMedia('Medical device monitoring scene.', '10-second 720p: Device and FDA logo. "Module 12."', 'image', 'beforeNarration', 'MDR overview.'), duration: createDuration('ACHC-ART-M12', 'M12-P01', 'overview', 'Overview', `Medical device reporting overview.`, 1), requiredForCompletion: true },
    { pageId: 'M12-P02', moduleId: 'ACHC-ART-M12', pageType: 'instruction', title: 'Reportable Events and Definitions', narrationText: `MDR reportable events for user facilities include patient deaths and serious injuries that medical devices may have caused or contributed to. Serious injury includes life-threatening injuries, injuries resulting in permanent damage or impairment, and injuries requiring medical intervention to prevent permanent damage. Malfunction is the failure of a device to meet its performance specifications. A malfunction is reportable when it is likely to cause or contribute to a death or serious injury if it recurs ΓÇö the regulation assumes recurrence. A report is required when the agency has information that reasonably suggests a device may have caused or contributed to a death or serious injury. If the chance is very remote, the event need not be reported. Adverse events include death, life-threatening events, hospitalization, disability, congenital anomaly, and required intervention to prevent permanent damage. User facilities must report deaths to both the FDA and manufacturer within ten work days. Serious injuries are reported to the manufacturer, and to the FDA only if the manufacturer is unknown, within ten work days. An annual report of deaths and serious injuries goes to the FDA every January first. All records are retained for a minimum of five years.`, contentHtml: `<h3>Reportable Events</h3><ul><li><strong>Death:</strong> ΓåÆ FDA + Manufacturer within 10 work days</li><li><strong>Serious Injury:</strong> ΓåÆ Manufacturer (+ FDA if manufacturer unknown) within 10 work days</li><li><strong>Malfunction:</strong> Reportable if likely to cause death/serious injury if recurrence</li></ul><h3>Serious Injury Types</h3><ol><li>Life-threatening</li><li>Permanent damage/impairment</li><li>Requires intervention to prevent permanent damage</li></ol><h3>Annual Report</h3><p>Deaths and serious injuries to FDA every January 1</p><h3>Record Retention</h3><p>Minimum 5 years</p>`, media: createMedia('MDR reporting flowchart: Death ΓåÆ FDA + Manufacturer; Serious Injury ΓåÆ Manufacturer (+ FDA if unknown).', '10-second 720p: Reporting paths shown.', 'image', 'duringNarration', 'MDR flowchart.'), duration: createDuration('ACHC-ART-M12', 'M12-P02', 'instruction', 'Reportable Events', `Death, serious injury, malfunction definitions and reporting paths.`, 2), challenge: { challengeId: 'M12-C01', lessonId: 'M12-P02', moduleId: 'ACHC-ART-M12', title: 'Event Classification', scenario: 'A patient\'s infusion pump repeatedly delivers medication at an incorrect rate. No patient harm has occurred yet, but the malfunction has happened three times this week.', narrationText: 'An infusion pump malfunctions repeatedly without causing harm yet. Is this reportable?', prompt: 'Is this a reportable malfunction?', interactionType: 'identify-the-risk', options: [createChallengeOption('a', 'Yes, this is reportable. A malfunction is reportable when it is likely to cause or contribute to a death or serious injury if it recurs. An infusion pump delivering incorrect medication rates could cause serious harm if the malfunction continues. Report to the Administrator immediately. Preserve the device.', 'Correct. Repeated malfunction of a medication delivery device is reportable because recurrence could cause serious harm.', true), createChallengeOption('b', 'No, since no harm occurred.', 'The regulation assumes malfunction will recur. If recurrence could cause death or serious injury, it is reportable regardless of whether harm has occurred.', false)], bestPracticeAnswer: 'Report malfunction. Preserve device. Document all three occurrences.', teachingPoint: 'The MDR regulation assumes malfunction will recur. Report malfunctions that could cause harm if they happen again.', documentationPrompt: 'Document: each malfunction occurrence with date/time, device details (manufacturer, model, serial, lot), patient impact, actions taken.', escalationPrompt: 'Report to Administrator immediately for FDA reporting determination.', estimatedInteractionMinutes: 4, requiredForProgression: true, graded: false, countsTowardFinalScore: false, reviewRequired: false }, requiredForCompletion: true },
