    { pageId: 'M12-P03', moduleId: 'ACHC-ART-M12', pageType: 'instruction', title: 'Reporting Chain, Documentation, and Device Preservation', narrationText: `When you encounter a potential device event, your immediate responsibilities are: protect the patient from further harm, preserve the device ΓÇö do not reuse, repair, or dispose of it before the investigation is complete, document everything including the manufacturer, model, serial number, and lot number, report to the Administrator immediately, and complete an employee report of the medical device hazard as soon as possible. The Administrator investigates, notifies the manufacturer if known, and forwards the report to the QAPI Committee for review. FDA notification uses Form 3500A (mandatory MedWatch form) and must be submitted within ten days from when any agency employee becomes aware the device may have contributed to death or injury. The report includes patient information, type of adverse event, description of the event, relevant lab data and patient history, manufacturer and device identification, initial reporter, facility information, and event problem codes. All records are retained for five years minimum. The QAPI Committee reviews summaries of all reported hazards, which are documented in meeting minutes. An annual in-service on Medical Device Reporting is provided with documentation of date, time, attendees, and content.`, contentHtml: `<h3>Your Immediate Actions</h3><ol><li>Protect patient from further harm</li><li>Preserve device ΓÇö NO reuse, repair, or disposal</li><li>Document: manufacturer, model, serial#, lot#</li><li>Report to Administrator immediately</li><li>Complete hazard report ASAP</li></ol><h3>Reporting Timeline</h3><p>FDA Form 3500A within 10 days of awareness</p><h3>Records</h3><p>Retained minimum 5 years. QAPI reviews all reports.</p>`, media: createMedia('Device preservation and reporting steps.', '10-second 720p: Steps shown. "Preserve ΓåÆ Report ΓåÆ Document."', 'image', 'duringNarration', 'Reporting steps.'), duration: createDuration('ACHC-ART-M12', 'M12-P03', 'instruction', 'Reporting Chain', `Reporting chain, documentation, device preservation.`, 2), challenge: { challengeId: 'M12-C02', lessonId: 'M12-P03', moduleId: 'ACHC-ART-M12', title: 'Device Preservation', scenario: 'After a patient is injured by a malfunctioning walker that collapsed, the patient\'s family wants to throw the walker away.', narrationText: 'The family wants to discard a device that injured a patient. What do you do?', prompt: 'Should the device be preserved?', interactionType: 'choose-best-response', options: [createChallengeOption('a', 'Explain to the family that the device must be preserved for investigation and regulatory reporting. Do not allow disposal, repair, or reuse. Tag or isolate the device. Document its condition, manufacturer, model, and serial number. Report to the Administrator.', 'Correct. Device preservation is critical for investigation and FDA reporting. Do not allow disposal.', true), createChallengeOption('b', 'Let them throw it away since it is their property.', 'The device is evidence for a regulatory report. It must be preserved.', false)], bestPracticeAnswer: 'Preserve device. No disposal, repair, or reuse. Document and report.', teachingPoint: 'Device preservation is mandatory for MDR reporting. Explain this to families clearly and professionally.', documentationPrompt: 'Document: device condition, manufacturer/model/serial/lot, injury details, family instructed on preservation.', escalationPrompt: 'Report to Administrator immediately for FDA reporting.', estimatedInteractionMinutes: 4, requiredForProgression: true, graded: false, countsTowardFinalScore: false, reviewRequired: false }, requiredForCompletion: true },
