export const examPool: ExamItem[] = ALL_MODULES.flatMap((mod) =>
  mod.finalAssessmentQuestions.map((q) => ({
    id: q.questionId,
    moduleCode: mod.moduleId.replace("ACHC-ART-", ""),
    prompt: q.questionText,
