          <div
            className="grid gap-sm"
            style={{
              gridTemplateColumns: `repeat(${lanes.length}, minmax(220px, 1fr))`,
              minWidth: `${Math.max(lanes.length * 220, 920)}px`,
            }}
          >
            {lanes.map((lane) => (
              <BoardLane key={lane.title} lane={lane} onCardClick={setSelectedCard} />
