          {filteredRows.length ? (
            <DataTable
              columns={columns}
              label="HH tag evidence map"
              rows={filteredRows}
              onRowClick={(row) => navigate(`/library/${encodeURIComponent(row.owner)}`, { state: { policyBackLabel: 'HH Tag Evidence Map', policyBackTo: '/framework/hh-evidence-map' } })}
            />
          ) : (
