const CLOUD_OP_TYPES = ['cloudrun.scaling.update', 'cloudrun.env.update', 'cloudrun.secret.attach', 'gcp.api.enable', 'deploy.labels.update', 'secretmanager.brad_entry.upsert', 'artifactregistry.brad_metadata.upsert'];
