type ViewState =
  | { view: "tracks" }
  | { view: "modules"; trackId: TrackId }
  | { view: "player"; moduleId: string; trackId: TrackId };

const CareIndeedOnboardingLMS: React.FC = () => {
  const navigate = useNavigate();
  const { state: learnerState } = useLearner();
  const [activeCategory, setActiveCategory] = useState<'onboarding' | 'annual' | 'advanced' | 'certificates'>(() => {
    const saved = localStorage.getItem("ci_lms_active_tab");
    return (saved === 'annual' || saved === 'onboarding' || saved === 'advanced') ? saved as any : 'onboarding';
  });

  const [viewState, setViewState] = useState<ViewState>(() => {
    const savedTab = localStorage.getItem("ci_lms_active_tab");
    if (savedTab === 'annual') {
      return { view: "modules", trackId: "ANN" };
    }
    if (savedTab === 'advanced') {
      return { view: "modules", trackId: "ADV" };
    }
    return { view: "tracks" };
  });

  const [rawProgress, setRawProgress] = useState<UserProgress>(() => {
    const saved = loadProgress();
    return saved || {
      currentTrack: null,
      currentModuleId: null,
      currentPage: 0,
      completedModules: {},
      examAttempts: {},
      startedAt: new Date().toISOString(),
    };
  });

  useEffect(() => {
    saveProgress(rawProgress);
  }, [rawProgress]);

  const progress = React.useMemo(() => {
    const completed = { ...rawProgress.completedModules };
    
    Object.entries(learnerState.moduleQuizPassed).forEach(([mid, passed]) => {
      if (passed) {
        if (mid.startsWith("m") && !mid.includes("-")) {
          const num = parseInt(mid.slice(1), 10);
          if (!isNaN(num)) {
            const achcId = `ACHC-ART-M${String(num).padStart(2, "0")}`;
            completed[achcId] = {
              moduleId: achcId,
              completedAt: new Date().toISOString(),
              examScore: 100,
              passed: true,
              timeSpentSeconds: 1200,
              attemptNumber: 1
            };
          }
        } else {
          completed[mid] = {
            moduleId: mid,
            completedAt: new Date().toISOString(),
            examScore: 100,
            passed: true,
            timeSpentSeconds: 1200,
            attemptNumber: 1
          };
        }
      }
    });

    return {
      ...rawProgress,
      completedModules: completed
    };
  }, [rawProgress, learnerState.moduleQuizPassed]);

  const handleModuleComplete = useCallback((result: ModuleResult) => {
    setRawProgress((prev) => ({
      ...prev,
      completedModules: { ...prev.completedModules, [result.moduleId]: result },
    }));
  }, []);

  const handleTabChange = (tab: 'onboarding' | 'annual' | 'advanced' | 'certificates') => {
    setActiveCategory(tab);
    localStorage.setItem("ci_lms_active_tab", tab);
    if (tab === 'onboarding') {
      setViewState({ view: "tracks" });
    } else if (tab === 'annual') {
      setViewState({ view: "modules", trackId: "ANN" });
    } else {
      setViewState({ view: "modules", trackId: "ADV" });
    }
  };

  return (
    <div style={{ color: BRAND.textPrimary }}>
      {/* Category Tabs */}
      <div style={{ display: "flex", borderBottom: `1px solid ${BRAND.border}`, marginBottom: "24px" }}>
        <button
          type="button"
          onClick={() => handleTabChange('onboarding')}
          style={{
            marginRight: "32px",
            paddingBottom: "12px",
            fontSize: "14px",
            fontWeight: 600,
            textTransform: "uppercase",
            letterSpacing: "0.05em",
            border: "none",
            background: "none",
            cursor: "pointer",
            borderBottom: activeCategory === 'onboarding' ? `2px solid ${BRAND.primary}` : "none",
            color: activeCategory === 'onboarding' ? BRAND.primary : BRAND.textSecondary,
            outline: "none",
          }}
        >
          Onboarding Training <span style={{ marginLeft: "6px", background: "#F1F5F9", padding: "2px 6px", borderRadius: "4px", fontSize: "10px", color: BRAND.textSecondary }}>41</span>
        </button>
        <button
          type="button"
          onClick={() => handleTabChange('annual')}
          style={{
            marginRight: "32px",
            paddingBottom: "12px",
            fontSize: "14px",
            fontWeight: 600,
            textTransform: "uppercase",
            letterSpacing: "0.05em",
            border: "none",
            background: "none",
            cursor: "pointer",
            borderBottom: activeCategory === 'annual' ? `2px solid ${BRAND.primary}` : "none",
            color: activeCategory === 'annual' ? BRAND.primary : BRAND.textSecondary,
            outline: "none",
          }}
        >
          ACHC Training <span style={{ marginLeft: "6px", background: "#F1F5F9", padding: "2px 6px", borderRadius: "4px", fontSize: "10px", color: BRAND.textSecondary }}>12</span>
        </button>
        <button
          type="button"
          onClick={() => handleTabChange('advanced')}
          style={{
            paddingBottom: "12px",
            fontSize: "14px",
            fontWeight: 600,
            textTransform: "uppercase",
            letterSpacing: "0.05em",
            border: "none",
            background: "none",
            cursor: "pointer",
            borderBottom: activeCategory === 'advanced' ? `2px solid ${BRAND.primary}` : "none",
            color: activeCategory === 'advanced' ? BRAND.primary : BRAND.textSecondary,
            outline: "none",
          }}
        >
          Advanced Training <span style={{ marginLeft: "6px", background: "#F1F5F9", padding: "2px 6px", borderRadius: "4px", fontSize: "10px", color: BRAND.textSecondary }}>1</span>
        </button>
        <button
          type="button"
          onClick={() => handleTabChange('certificates')}
          style={{
            paddingBottom: "12px",
            fontSize: "14px",
            fontWeight: 600,
            textTransform: "uppercase",
            letterSpacing: "0.05em",
            border: "none",
            background: "none",
            cursor: "pointer",
            borderBottom: activeCategory === 'certificates' ? `2px solid ${BRAND.primary}` : "none",
            color: activeCategory === 'certificates' ? BRAND.primary : BRAND.textSecondary,
            outline: "none",
          }}
        >
          My Certificates
        </button>
      </div>

      {activeCategory === 'annual' && viewState.view === 'modules' && (
        <div style={{ background: "#F0FAFA", padding: "16px 20px", borderRadius: "8px", marginBottom: "24px", fontSize: "14px", boxShadow: "0 1px 3px rgba(0,0,0,0.05)" }}>
          <p style={{ margin: 0, fontWeight: 600, color: BRAND.primaryLight, textTransform: "uppercase", letterSpacing: "0.05em", fontSize: "12px" }}>ACHC Required ΓÇö Field Worker Edition</p>
          <p style={{ margin: "4px 0 0 0", color: BRAND.textSecondary }}>
            12 modules ┬╖ On hire + annually ┬╖ 80% passing threshold ┬╖ All modules include TTS narration and scenario-based challenges.
          </p>
        </div>
      )}

      {activeCategory === 'advanced' && viewState.view === 'modules' && (
        <div style={{ background: "#FFFBF0", padding: "16px 20px", borderRadius: "8px", marginBottom: "24px", fontSize: "14px", boxShadow: "0 1px 3px rgba(0,0,0,0.05)" }}>
          <p style={{ margin: 0, fontWeight: 600, color: BRAND.warning, textTransform: "uppercase", letterSpacing: "0.05em", fontSize: "12px" }}>Advanced Training ΓÇö Plan of Care &amp; Compliance</p>
          <p style={{ margin: "4px 0 0 0", color: BRAND.textSecondary }}>
            Advanced compliance training covering establishment, specificity, defensibility, and clinical alignment of the CMS-485 Plan of Care.
          </p>
        </div>
      )}

      {activeCategory === 'certificates' ? (
        <MyCertificatesView />
      ) : (
        <main style={{ padding: "12px 0" }}>
          {viewState.view === "tracks" && (
            <TrackSelector
              onSelectTrack={(t) => setViewState({ view: "modules", trackId: t })}
              progress={progress}
            />
          )}
          {viewState.view === "modules" && (
            <ModuleList
              trackId={viewState.trackId}
              progress={progress}
              onSelectModule={(mid) => {
                let standardId = mid;
                if (mid.toUpperCase().startsWith("ACHC-ART-")) {
                  const match = mid.match(/M(\d+)/i);
                  standardId = match ? `m${Number(match[1])}` : mid;
                }
                navigate(`/journey/module/${standardId}`);
              }}
              onBack={() => {
                if (activeCategory === 'annual' || activeCategory === 'advanced') {
                  handleTabChange('onboarding');
                } else {
                  setViewState({ view: "tracks" });
                }
              }}
            />
          )}
          {viewState.view === "player" && (
            <ModulePlayer
              moduleId={viewState.moduleId}
              progress={progress}
              onComplete={handleModuleComplete}
              onBack={() => setViewState({ view: "modules", trackId: viewState.trackId })}
            />
          )}
        </main>
      )}
    </div>
  );
};



