            </h3>
            <ul className="text-sm text-secondary grid gap-sm list-disc pl-md">
              {latestUpdates.map((update) => <li key={update}>{update}</li>)}
            </ul>
          </section>
        </aside>
      </section>
    </section>
  );
}

