import { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { GitBranch, Landmark, Workflow } from 'lucide-react';
import { DataTable, MetricGrid, SurfaceCard, type DataTableColumn, type MetricTileData, type SurfaceCardData } from '../../components';
import { cx } from '../../utils/classNames';
import { WORKFLOWS } from '@/policy/data/workflows.generated';
import {
  resolveWorkflowPolicyRefs,
} from '@/policy/workflows/utils/resolveWorkflowPolicyRefs';
import { resolveFormTitle } from '@/policy/data/formIdAliases';



export const getWorkflowDetail = (id: string) => {
  const wf = WORKFLOWS[id];
  if (wf) {
    const res = resolveWorkflowPolicyRefs(wf);
    const policyStr = res.effectivePolicyRefs.length > 0
      ? res.effectivePolicyRefs.map(r => r.title).join(', ')
      : (wf.policyRefs || []).join(', ');
    const formStr = (wf.requiredForms || []).map(fid => `${fid} ${resolveFormTitle(fid)}`).join(', ') || (wf.requiredFormsRaw || 'ΓÇö');
    const evidenceStr = wf.outputs || wf.auditRequirements || wf.sla || 'ΓÇö';
    const stepCount = wf.steps?.length ?? 0;
    const formCount = wf.requiredForms?.length ?? 0;
    return {
      purpose: wf.processOverview || 'Reference workflow definition from generated library.',
      policies: policyStr || 'ΓÇö',
      forms: formStr,
      evidence: evidenceStr,
      roles: (wf.roles?.primary || []).concat(wf.roles?.supporting || [], wf.roles?.approval || []).filter(Boolean).join(' / '),
      triggers: (wf.triggers || []).map((t: any) => t.description).join(' | ') || wf.cadence?.interval || 'ΓÇö',
      linkedWorkflows: (wf.dependencies || []).map((d: any) => d.upstreamId).join(', ') || 'ΓÇö',
      history: [
        { item: `Cadence: ${wf.cadence?.interval ?? 'ΓÇö'} (${wf.cadence?.kind ?? 'ΓÇö'})`, status: 'Defined', tone: 'teal' as const },
        { item: `${stepCount} steps; ${formCount} forms; roles: ${(wf.roles?.primary || []).join('/')}`, status: 'Ready', tone: 'teal' as const },
      ],
    };
  }
  // Honest diagnostic for unresolved ID - no fabricated data
  return null;
};

export interface WorkflowRow extends Record<string, string> {
  domain: string;
  domainOwner: string;
  frequency: string;
  risk: string;
  status: string;
  title: string;
  workflowId: string;
}

export const workflowRows: readonly WorkflowRow[] = Object.values(WORKFLOWS).map((wf: any) => {
  const cad = wf.cadence || {};
  const freqRaw = cad.interval || 'ΓÇö';
  const frequency = typeof freqRaw === 'string' ? (freqRaw.charAt(0).toUpperCase() + freqRaw.slice(1)) : 'ΓÇö';
  const riskRaw = (wf.metrics?.declaredRisk || 'moderate').toLowerCase();
  const risk = /immediate_jeopardy|high/.test(riskRaw) ? 'High' : /moderate/.test(riskRaw) ? 'Medium' : 'Low';
  const primary = wf.roles?.primary?.[0] || wf.roles?.supporting?.[0] || wf.domain || 'ΓÇö';
  return {
    domain: wf.domain || 'ΓÇö',
    domainOwner: String(primary),
    frequency,
    risk,
    status: 'active',
    title: wf.title || wf.id,
    workflowId: wf.id,
  };
});

const workflowMetrics: readonly MetricTileData[] = [
  { label: 'Workflows', value: String(workflowRows.length), helper: 'All generated records', tone: 'teal' },
  { label: 'High risk', value: String(workflowRows.filter((r: WorkflowRow) => r.risk === 'High').length), helper: 'From metrics', tone: 'orange' },
  { label: 'Domains', value: String(Array.from(new Set(workflowRows.map((r: WorkflowRow) => r.domain))).length), helper: 'Coverage', tone: 'teal' },
];

const workflowColumns: readonly DataTableColumn<WorkflowRow>[] = [
  { key: 'workflowId', label: 'Workflow ID' },
  { key: 'title', label: 'Workflow title' },
  { key: 'domain', label: 'Domain' },
  { key: 'risk', label: 'Risk' },
  { key: 'frequency', label: 'Frequency' },
  { key: 'status', label: 'Status', status: true },
];

// workflowRows derived from real generated WORKFLOWS (full resolution of ids, titles, cadence, roles, risk, forms).

const workflowCards: readonly SurfaceCardData[] = workflowRows.slice(0, 3).map((row, idx) => {
  const wf: any = WORKFLOWS[row.workflowId] || {};
  const stepC = wf.steps?.length || 0;
  const formC = (wf.requiredForms || []).length;
  return {
    body: `${row.frequency} ΓÇó ${row.risk} risk ΓÇó ${stepC} steps, ${formC} forms. Roles: ${row.domainOwner}. Educational reference only.`,
    icon: idx === 0 ? Workflow : idx === 1 ? GitBranch : Landmark,
    progress: 65 + ((idx * 11) % 25),
    status: 'active',
    title: row.title.length > 28 ? row.title.slice(0, 25) + 'ΓÇª' : row.title,
    tone: row.risk === 'High' ? 'orange' : 'teal',
  } as SurfaceCardData;
});

const allDomains = Array.from(new Set(workflowRows.map((r) => r.domain)));
const allRisks = Array.from(new Set(workflowRows.map((r) => r.risk)));

export default function WorkflowsScreen() {
  const navigate = useNavigate();
  const [searchQuery, setSearchQuery] = useState('');
  const [activeDomains, setActiveDomains] = useState<readonly string[]>([...allDomains]);
  const [activeRisks, setActiveRisks] = useState<readonly string[]>([...allRisks]);

  const filteredRows = workflowRows.filter((row) => {
    const q = searchQuery.trim().toLowerCase();
    const matchesSearch =
      !q ||
      row.workflowId.toLowerCase().includes(q) ||
      row.title.toLowerCase().includes(q) ||
      row.domain.toLowerCase().includes(q) ||
      row.domainOwner.toLowerCase().includes(q);
    const matchesDomain = activeDomains.includes(row.domain);
    const matchesRisk = activeRisks.includes(row.risk);
    return matchesSearch && matchesDomain && matchesRisk;
  });

  function toggleDomain(domain: string) {
    setActiveDomains((curr) =>
      curr.includes(domain) ? curr.filter((d) => d !== domain) : [...curr, domain]
    );
  }

  function toggleRisk(risk: string) {
    setActiveRisks((curr) =>
      curr.includes(risk) ? curr.filter((r) => r !== risk) : [...curr, risk]
    );
  }

  function openRealDetail(row: WorkflowRow) {
    // Click to real detail page first. Detail links to reference swimlane.
    navigate(`/workflows/${encodeURIComponent(row.workflowId)}`);
  }

  return (
    <section className="grid gap-xl" data-hash-id="workflows" data-route="/workflows" data-template="matrix">
      <MetricGrid metrics={workflowMetrics} />

      {/* Real generated workflow library preview (from WORKFLOWS). Click opens reference detail. */}
      <div className="grid gap-md grid-cols-1 md:grid-cols-2 lg:grid-cols-3">
        {workflowRows.slice(0, 6).map((row) => {
          const wf: any = WORKFLOWS[row.workflowId] || {};
          const stepC = wf.steps?.length || 0;
          const formC = (wf.requiredForms || []).length;
          return (
            <div key={row.workflowId} className="rounded-lg border border-hairline bg-surface-glass p-lg hover:shadow-rest transition cursor-pointer overflow-hidden" onClick={() => {
              openRealDetail(row);
            }}>
              <div className="flex items-center justify-between">
                <div className="text-tag uppercase tracking-tag text-brand-teal">{row.workflowId}</div>
                <span className="text-[10px] px-sm py-0.5 rounded bg-surface-glass backdrop-blur-md shadow-glass-inset">{row.status}</span>
              </div>
              <div className="mt-sm text-base font-medium text-ink">{row.title}</div>
              <div className="mt-xs text-sm text-secondary">{row.domain} ΓÇó {row.frequency} ΓÇó {row.risk} risk</div>
              <div className="mt-md text-[10px] text-muted">{stepC} steps ΓÇó {formC} forms ΓÇó {row.domainOwner}</div>
            </div>
          );
        })}
      </div>

      <div className="flex flex-wrap items-end justify-between gap-md">
        <div>
          <div className="text-tag uppercase tracking-tag text-muted">Workflow Library</div>
          <div className="text-h2 font-medium text-brand-teal-deep">Active workflows (generated records)</div>
        </div>
        <div className="flex flex-wrap gap-sm">
          <input
            type="text"
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            placeholder="Search ID, title, domain..."
            className="min-w-[220px] rounded-md border border-card bg-surface-glass backdrop-blur-md shadow-glass-inset px-md py-sm text-sm placeholder:text-muted focus-visible:outline-none focus-visible:shadow-focus"
            aria-label="Search workflows"
          />
        </div>
      </div>

      <div className="flex flex-wrap gap-sm" aria-label="Domain and risk filters">
        <span className="text-tag uppercase tracking-tag text-muted self-center mr-xs">Domain:</span>
        {allDomains.map((domain) => {
          const on = activeDomains.includes(domain);
          return (
            <button
              key={domain}
              type="button"
              onClick={() => toggleDomain(domain)}
              className={cx(
                'rounded-sm border px-md py-xs text-tag uppercase tracking-tag transition',
                on
                  ? 'border-brand-teal bg-brand-teal text-on-brand'
                  : 'border-hairline bg-surface-glass backdrop-blur-md shadow-glass-inset text-brand-teal hover:bg-surface-glass hover:backdrop-blur-md'
              )}
            >
              {domain}
            </button>
          );
        })}
        <span className="text-tag uppercase tracking-tag text-muted self-center ml-md mr-xs">Risk:</span>
        {allRisks.map((risk) => {
          const on = activeRisks.includes(risk);
          const toneClass = risk === 'High' ? 'border-tone-orange-border text-tone-orange-text' : risk === 'Medium' ? 'border-tone-amber-border text-tone-amber-text' : 'border-tone-green-border text-tone-green-text';
          return (
            <button
              key={risk}
              type="button"
              onClick={() => toggleRisk(risk)}
              className={cx(
                'rounded-sm border px-md py-xs text-tag uppercase tracking-tag transition',
                on ? 'bg-surface-glass backdrop-blur-md shadow-glass-inset border-brand-teal text-brand-teal' : `bg-surface-glass backdrop-blur-md shadow-glass-inset ${toneClass} opacity-70 hover:opacity-100`
              )}
            >
              {risk}
            </button>
          );
        })}
      </div>

      <section className="grid gap-lg desktop:grid-cols-[minmax(0,3fr)_minmax(340px,2fr)]">
        <section aria-label="Workflows library matrix" className="rounded-lg border border-card bg-surface-glass backdrop-blur-md shadow-glass-inset p-xl shadow-rest overflow-hidden">
          <DataTable
            columns={workflowColumns}
            label="Workflows library matrix"
            rows={filteredRows}
            onRowClick={(row) => {
              openRealDetail(row);
            }}
          />
          {filteredRows.length === 0 && (
            <div className="p-md text-sm text-muted">No workflows match current filters.</div>
          )}
        </section>

        <aside className="grid content-start gap-lg" aria-label="Workflow swimlane cards">
          {workflowCards.map((card) => (
            <SurfaceCard card={card} key={card.title} />
          ))}
        </aside>
      </section>
    </section>
  );
}

import { useEffect } from 'react';
import { Link, matchPath, useLocation } from 'react-router-dom';
import { cx } from '../utils/classNames';
import { primaryNavItems } from '../routing/navigationManifest';
import { V6_ROUTES } from '../routing/routeRegistry';
import { getIdentity, setIdentity, DEV_IDENTITIES } from '../screens/brad/bradApi';

export function Sidebar() {
  const { pathname } = useLocation();

  const findActive = (items: readonly any[], path: string): { parent?: any; child?: any } | null => {
    for (const item of items) {
      const baseHashMatch = item.hashIds && item.hashIds.some((h: string) =>
        V6_ROUTES.some(r => r.hashId === h && matchPath({ path: r.path, end: !r.path.endsWith('/*') }, path))
      );
      const baseMatchPath = item.matchPaths && item.matchPaths.some((mp: string) => matchPath({ path: mp, end: false }, path));
      const baseExactOrPrefix = path === item.to || path.startsWith(item.to + '/');
      const matchesParent = baseHashMatch || baseMatchPath || baseExactOrPrefix;
      if (matchesParent) {
        return { parent: item };
      }
    }
    return null;
  };

  const active = findActive(primaryNavItems, pathname);

  useEffect(() => {
    const activeLink = document.querySelector<HTMLElement>('[data-sidebar-active="true"]');
    activeLink?.scrollIntoView({ behavior: 'smooth', block: 'center' });
  }, [pathname]);

  return (
    <aside className="sticky top-0 z-command h-screen w-sidebar shrink-0 overflow-hidden border-r border-hairline bg-surface-glass backdrop-blur-md shadow-glass-inset text-ink shadow-sidebar backdrop-blur-xl flex flex-col">
      {/* Top spacer clears the fixed hamburger + logo cluster rendered by V6Shell. */}
      <div className="relative z-10 shrink-0 px-lg pt-[64px]" aria-hidden />

      <nav
        aria-label="V6 routes"
        className="flex-1 overflow-y-auto px-lg pb-2xl pt-md"
        style={{
          maskImage: 'linear-gradient(to bottom, transparent 0, black 34px, black calc(100% - 32px), transparent 100%)',
          WebkitMaskImage: 'linear-gradient(to bottom, transparent 0, black 34px, black calc(100% - 32px), transparent 100%)',
        }}
      >
        <div className="grid gap-xl">
          {/* PRIMARY OPERATIONS */}
          <div className="text-[10px] font-medium uppercase tracking-[0.2em] text-muted px-sm">PRIMARY OPERATIONS</div>
          {['brad', 'dashboard'].map(id => {
            const item = primaryNavItems.find(i => i.id === id);
            if (!item) return null; // guard: hidden/removed nav items must not crash the sidebar
            const isActive = active?.parent?.id === item.id;
            return (
              <Link
                key={item.id}
                to={item.to}
                aria-current={isActive ? 'page' : undefined}
                className={cx(
                  'flex min-h-row items-center gap-md rounded-lg px-md py-sm text-sm font-medium transition duration-fast ease-standard',
                  'focus-visible:outline-none focus-visible:shadow-focus',
                  isActive
                    ? 'bg-brand-teal-deep text-on-brand shadow-rest'
                    : 'text-brand-teal-deep hover:translate-x-1 hover:bg-surface-hover hover:text-brand-teal',
                )}
                data-sidebar-active={isActive ? 'true' : undefined}
              >
                <span>{item.label}</span>
              </Link>
            );
          })}

          {/* COMPLIANCE EXECUTION */}
          <div className="text-[10px] font-medium uppercase tracking-[0.2em] text-muted px-sm mt-sm">COMPLIANCE EXECUTION</div>
          {['ces', 'taxonomy', 'onboarding'].map(id => {
            const item = primaryNavItems.find(i => i.id === id);
            if (!item) return null; // guard: hidden/removed nav items must not crash the sidebar
            const isActive = active?.parent?.id === item.id;
            return (
              <Link
                key={item.id}
                to={item.to}
                aria-current={isActive ? 'page' : undefined}
                className={cx(
                  'flex min-h-row items-center gap-md rounded-lg px-md py-sm text-sm font-medium transition duration-fast ease-standard',
                  'focus-visible:outline-none focus-visible:shadow-focus',
                  isActive
                    ? 'bg-brand-teal-deep text-on-brand shadow-rest'
                    : 'text-brand-teal-deep hover:translate-x-1 hover:bg-surface-hover hover:text-brand-teal',
                )}
                data-sidebar-active={isActive ? 'true' : undefined}
              >
                <span>{item.label}</span>
              </Link>
            );
          })}

          {/* ADMINISTRATION / KNOWLEDGE */}
          <div className="text-[10px] font-medium uppercase tracking-[0.2em] text-muted px-sm mt-sm">ADMINISTRATION / KNOWLEDGE</div>
          {['help-center', 'admin'].map(id => {
            const item = primaryNavItems.find(i => i.id === id);
            if (!item) return null; // guard: nav items can be removed without crashing the sidebar
            const isActive = active?.parent?.id === item.id;
            return (
              <Link
                key={item.id}
                to={item.to}
                aria-current={isActive ? 'page' : undefined}
                className={cx(
                  'flex min-h-row items-center gap-md rounded-lg px-md py-sm text-sm font-medium transition duration-fast ease-standard',
                  'focus-visible:outline-none focus-visible:shadow-focus',
                  isActive
                    ? 'bg-brand-teal-deep text-on-brand shadow-rest'
                    : 'text-brand-teal-deep hover:translate-x-1 hover:bg-surface-hover hover:text-brand-teal',
                )}
                data-sidebar-active={isActive ? 'true' : undefined}
              >
                <span>{item.label}</span>
              </Link>
            );
          })}
        </div>
      </nav>

      {/* Footer: acting-as identity (server independently verifies Super Admin). */}
      <div className="shrink-0 border-t border-hairline px-lg py-md">
        <label className="block text-[10px] font-medium uppercase tracking-[0.2em] text-muted">
          Acting as
        </label>
        <select
          aria-label="Acting-as identity (server verifies Super Admin)"
          title="Review identity ΓÇö the server independently verifies Super Admin status"
          defaultValue={getIdentity().userId}
          onChange={(e) => { setIdentity(e.target.value); window.location.reload(); }}
          className="mt-1 w-full rounded-md border border-hairline bg-surface-glass backdrop-blur-md shadow-glass-inset px-2 py-1.5 text-xs text-ink focus-visible:outline-none focus-visible:shadow-focus"
        >
          {DEV_IDENTITIES.map((d) => (
            <option key={d.userId} value={d.userId}>{d.displayName}</option>
          ))}
        </select>
      </div>
    </aside>
  );
}

