function FloatingActionRail({
  renderFeedbackPanel,
  feedbackPanelVisible,
  onFeedbackOpen,
  onFeedbackClose,
}: {
  renderFeedbackPanel: boolean;
  feedbackPanelVisible: boolean;
  onFeedbackOpen: () => void;
  onFeedbackClose: () => void;
}) {
  type PageElementContext = {
    label: string;
    kind: string;
    detail: string;
  };

  const navigate = useNavigate();
  const { pathname } = useLocation();
  const threads = useThreadStore((s) => s.threads);
  const activeThreadCount = threads.filter((thread) => thread.status !== 'archived' && thread.status !== 'duplicate').length;
  const [threadMode, setThreadMode] = useState<'list' | 'new' | 'detail'>('list');
  const [selectedThreadId, setSelectedThreadId] = useState<string | null>(null);
  const [pageElements, setPageElements] = useState<PageElementContext[]>([]);
  const [selectedElement, setSelectedElement] = useState<PageElementContext | null>(null);

  const scanCurrentPageElements = (): PageElementContext[] => {
    const main = document.getElementById('main-content');
    if (!main) return [];
    const nodes = Array.from(
      main.querySelectorAll<HTMLElement>(
        'h1,h2,h3,[data-route],[data-hash-id],button,a,input,textarea,select,[role="button"],[aria-label]',
      ),
    );
    const seen = new Set<string>();
    return nodes
      .map((node) => {
        const text = (node.innerText || node.getAttribute('aria-label') || node.getAttribute('placeholder') || node.getAttribute('data-route') || '').trim();
        if (!text || text.length < 2) return null;
        const label = text.replace(/\s+/g, ' ').slice(0, 88);
        const kind =
          node.tagName.toLowerCase().match(/^h[1-3]$/) ? 'section' :
          node.tagName.toLowerCase() === 'a' ? 'link' :
          ['button', 'select', 'input', 'textarea'].includes(node.tagName.toLowerCase()) || node.getAttribute('role') === 'button' ? 'control' :
          'page';
        const detail = [
          node.getAttribute('data-route') ? `route ${node.getAttribute('data-route')}` : '',
          node.getAttribute('data-hash-id') ? `view ${node.getAttribute('data-hash-id')}` : '',
          node.id ? `#${node.id}` : '',
        ].filter(Boolean).join(' ┬╖ ') || pathname;
        const key = `${kind}:${label}:${detail}`;
        if (seen.has(key)) return null;
        seen.add(key);
        return { label, kind, detail };
      })
      .filter((item): item is PageElementContext => Boolean(item))
      .slice(0, 18);
  };

  const openFeedback = () => {
    const elements = scanCurrentPageElements();
    setPageElements(elements);
    setSelectedElement(elements[0] ?? null);
    setThreadMode('list');
    setSelectedThreadId(null);
    onFeedbackOpen();
  };

  const openThread = (threadId: string) => {
    setSelectedThreadId(threadId);
    setThreadMode('detail');
  };

  const openThreadRoute = (route: string) => {
    onFeedbackClose();
    navigate(route);
  };

  return (
    <>
      <div className="fixed right-5 top-1/2 z-popover flex -translate-y-1/2 flex-col items-center gap-4">
        <button
          type="button"
          onClick={openFeedback}
          aria-label="Open feedback"
          className="relative grid h-11 w-11 place-items-center rounded-full border border-hairline bg-white/65 text-ink shadow-rest backdrop-blur-[33px] transition duration-300 ease-standard hover:-translate-y-0.5 hover:bg-white/85 hover:text-brand-teal-deep hover:shadow-hover"
        >
          <MessageCircle className="h-5 w-5" aria-hidden />
          <span className="absolute -right-1 -top-1 grid h-5 min-w-5 place-items-center rounded-full bg-white px-1 text-[10px] font-medium text-muted shadow-rest">
            {Math.min(activeThreadCount, 99)}
          </span>
        </button>
        <button
          type="button"
          onClick={() => navigate('/help')}
          data-tour-target="nav.help"
          aria-label="Open help center"
          className="grid h-11 w-11 place-items-center rounded-full border border-hairline bg-white/65 text-ink shadow-rest backdrop-blur-[33px] transition duration-300 ease-standard hover:-translate-y-0.5 hover:bg-white/85 hover:text-brand-teal-deep hover:shadow-hover"
        >
          <HelpCircle className="h-5 w-5" aria-hidden />
        </button>
        <button
          type="button"
          aria-label="Share"
          className="grid h-11 w-11 place-items-center rounded-full border border-hairline bg-white/65 text-ink shadow-rest backdrop-blur-[33px] transition duration-300 ease-standard hover:-translate-y-0.5 hover:bg-white/85 hover:text-brand-teal-deep hover:shadow-hover"
        >
          <Share2 className="h-5 w-5" aria-hidden />
        </button>
        <button
          type="button"
          aria-label="Information"
          className="grid h-11 w-11 place-items-center rounded-full border border-hairline bg-white/65 text-ink shadow-rest backdrop-blur-[33px] transition duration-300 ease-standard hover:-translate-y-0.5 hover:bg-white/85 hover:text-brand-teal-deep hover:shadow-hover"
        >
          <Info className="h-5 w-5" aria-hidden />
        </button>
      </div>

      {renderFeedbackPanel && (
        <aside
          className={cx(
            'fixed right-0 top-0 z-command flex h-full w-[min(760px,92vw)] flex-col overflow-hidden border-l-[10px] border-hairline bg-white/82 shadow-hover backdrop-blur-[33px] transition-transform duration-500 ease-standard',
            feedbackPanelVisible ? 'translate-x-0' : 'translate-x-full',
          )}
          aria-label="Feedback"
        >
          <div className="flex min-h-24 items-center gap-7 border-b border-hairline px-8">
            <button
              type="button"
              onClick={onFeedbackClose}
              aria-label="Close feedback"
              className="grid h-12 w-12 place-items-center rounded-full border border-hairline bg-white/70 text-muted shadow-rest transition duration-300 ease-standard hover:text-brand-teal-deep"
            >
              <X className="h-6 w-6" aria-hidden />
            </button>
            <div className="flex flex-1 items-center gap-5">
              <button type="button" aria-label="Favorite" className="grid h-14 w-14 place-items-center rounded-full border border-hairline bg-white/70 text-ink shadow-rest">
                <Heart className="h-6 w-6" aria-hidden />
              </button>
              <button type="button" aria-label="Bookmark" className="grid h-14 w-14 place-items-center rounded-full border border-hairline bg-white/70 text-ink shadow-rest">
                <Bookmark className="h-6 w-6" aria-hidden />
              </button>
              <button type="button" aria-label="Share" className="grid h-14 w-14 place-items-center rounded-full border border-hairline bg-white/70 text-ink shadow-rest">
                <Share2 className="h-6 w-6" aria-hidden />
              </button>
            </div>
            <button type="button" aria-label="Information" className="grid h-14 w-14 place-items-center rounded-full border border-hairline bg-white/70 text-ink shadow-rest">
              <Info className="h-6 w-6" aria-hidden />
            </button>
          </div>
          <div className="min-h-0 flex-1 overflow-auto px-8 py-10 tablet-p:px-14">
            <h2 className="mb-6 text-[32px] font-medium leading-tight text-ink">Feedback</h2>
            <div className="mb-6 rounded-lg border border-card bg-white/45 p-5 shadow-rest backdrop-blur-[33px]">
              <div className="mb-3 flex flex-wrap items-center justify-between gap-3">
                <div>
                  <p className="text-sm font-medium text-ink">Current page context</p>
                  <p className="text-xs text-muted">{pathname}</p>
                </div>
                <button
                  type="button"
                  onClick={() => {
                    const elements = scanCurrentPageElements();
                    setPageElements(elements);
                    setSelectedElement(elements[0] ?? null);
                  }}
                  className="rounded-md border border-hairline bg-white/60 px-3 py-1.5 text-xs text-secondary transition duration-300 hover:bg-white"
                >
                  Refresh elements
                </button>
              </div>
              <div className="flex gap-2 overflow-x-auto pb-1">
                {pageElements.length === 0 ? (
                  <span className="rounded-full bg-white/60 px-3 py-1.5 text-xs text-muted">No page elements detected</span>
                ) : pageElements.map((element) => (
                  <button
                    key={`${element.kind}-${element.label}-${element.detail}`}
                    type="button"
                    onClick={() => {
                      setSelectedElement(element);
                      setThreadMode('new');
                    }}
                    className={cx(
                      'shrink-0 rounded-full border px-3 py-1.5 text-xs transition duration-300',
                      selectedElement?.label === element.label && selectedElement.detail === element.detail
                        ? 'border-brand-teal bg-brand-teal text-on-brand'
                        : 'border-hairline bg-white/60 text-secondary hover:bg-white',
                    )}
                  >
                    {element.kind}: {element.label}
                  </button>
                ))}
              </div>
            </div>
            <div className="rounded-lg border border-card bg-white/45 p-5 shadow-rest backdrop-blur-[33px] [&_input]:relative [&_input]:z-base [&_textarea]:relative [&_textarea]:z-base">
              {threadMode === 'new' ? (
                <ThreadComposer
                  source={{ kind: 'general' }}
                  defaultType="general_question"
                  defaultCategory="other"
                  initialTitle={selectedElement ? `Feedback on ${selectedElement.label}` : `Feedback on ${pathname}`}
                  initialBody={[
                    `Page: ${pathname}`,
                    selectedElement ? `Element: ${selectedElement.kind} - ${selectedElement.label}` : '',
                    selectedElement?.detail ? `Element detail: ${selectedElement.detail}` : '',
                  ].filter(Boolean).join('\n')}
                  onDone={openThread}
                  onCancel={() => setThreadMode('list')}
                />
              ) : threadMode === 'detail' && selectedThreadId ? (
                <ThreadDetailPage
                  threadId={selectedThreadId}
                  onBack={() => setThreadMode('list')}
                  onOpenThread={openThread}
                  onOpenRoute={openThreadRoute}
                />
              ) : (
                <ThreadsPage
                  onOpenThread={openThread}
                  onStartThread={() => setThreadMode('new')}
                />
              )}
            </div>
          </div>
        </aside>
      )}
    </>
  );
}

type ShellSubnavItem = NavItem & { brand?: boolean };

function cleanPolicySectionTitle(title: string): string {
  return title.replace(/\\([.\-#|*_])/g, '$1').trim();
}

function getPolicySectionNavItems(pathname: string): ShellSubnavItem[] {
  const match = /^\/library\/([^/]+)\/?$/.exec(pathname);
  if (!match) return [];
  const policyId = decodeURIComponent(match[1]);
  const content = getPolicyContent(policyId);
  if (!content) return [];
  return [...content.sections]
    .sort((a, b) => a.order - b.order)
    .filter((section) => section.order !== 1 && section.level <= 2)
    .map((section) => ({
      id: `policy-section-${section.id}`,
      label: cleanPolicySectionTitle(section.title),
      to: `#section-${section.id}`,
      hashIds: [],
    }));
}

function getShellSubnavItems(pathname: string): ShellSubnavItem[] {
  const p = (pathname || '').split(/[?#]/)[0];
  const isCESGroup =
    p.startsWith('/ces/') ||
    p.startsWith('/events/') ||
    p === '/audit' ||
    p === '/evidence' ||
    p.startsWith('/evidence/') ||
    p.startsWith('/compliance/');
  const isTaxonomyGroup =
    p.startsWith('/framework') ||
    p.startsWith('/library') ||
    p.startsWith('/forms') ||
    p.startsWith('/taxonomy') ||
    p.startsWith('/achc') ||
    p.startsWith('/workflows') ||
    p.startsWith('/policy-lifecycle') ||
    p === '/policy-approvals' ||
    p === '/pm/approvals';
  const isOnboardingGroup = p.startsWith('/journey') || p.startsWith('/onboarding-v2');
  const isSystemGroup = p.startsWith('/system-documentation') || p === '/hubstaff';
  const isAdminGroup = p.startsWith('/admin/');

  if (isCESGroup) {
    const cesItemsById = new Map(workspaceSubnavItems.ces.map((item) => [item.id, item]));
    const orderedItems = [
      cesItemsById.get('defensible-2') ? { ...cesItemsById.get('defensible-2')!, label: 'DefenCIble', brand: true } : undefined,
      cesItemsById.get('ces-calendar'),
      cesItemsById.get('master-controls'),
    ];
    return orderedItems.filter((item): item is ShellSubnavItem => Boolean(item));
  }
  if (isTaxonomyGroup) return workspaceSubnavItems.taxonomy;
  if (isOnboardingGroup) return [];
  if (isSystemGroup) return workspaceSubnavItems['system-docs'];
  if (isAdminGroup) return workspaceSubnavItems.admin;
  return [];
}

function ShellSubnav({ items, currentPath }: { items: ShellSubnavItem[]; currentPath: string }) {
  const p = (currentPath || '').split(/[?#]/)[0];
  const safeItems = items.filter((item): item is ShellSubnavItem => Boolean(item?.to));
  const activeTo = safeItems.reduce((best, item) => {
    const to = item.to;
    const matches = item.matchPaths
      ? item.matchPaths.some((match) => matchPath({ path: match, end: false }, p))
      : p === to || p.startsWith(`${to}/`);
    if (!matches) return best;
    return !best || to.length > best.length ? to : best;
  }, null as string | null);

  return (
    <nav
      className="flex min-w-0 flex-1 items-center justify-start gap-2 overflow-x-auto whitespace-nowrap pl-0 pr-sm text-sm [scrollbar-width:none] [&::-webkit-scrollbar]:hidden"
      aria-label="Workspace subnav"
    >
      {safeItems.map((item) => {
        const isActive = activeTo === item.to;
        const className = cx(
          'shrink-0 rounded-full border border-transparent bg-transparent px-3 py-2 text-brand-teal shadow-none backdrop-blur-none transition duration-300 ease-standard hover:text-brand-teal-deep',
          isActive ? 'font-medium text-brand-teal-deep' : '',
        );
        return (
          <Link
            key={item.to}
            to={item.to}
            data-tour-target={item.id === 'defensible-2' ? 'nav.evidence' : undefined}
            aria-current={isActive ? 'page' : undefined}
            className={className}
          >
            {item.brand ? (
              <DefenCIbleWordmark glow />
            ) : item.label}
          </Link>
        );
      })}
    </nav>
  );
}

function PolicySectionSubnav({ items }: { items: ShellSubnavItem[] }) {
  return (
    <nav
      aria-label="Policy section navigation"
      className="flex min-w-0 items-center gap-xl overflow-x-auto whitespace-nowrap pl-[calc(4rem+1rem)] pr-sm text-sm [scrollbar-width:none] [&::-webkit-scrollbar]:hidden"
    >
      {items.map((item, index) => (
        <a
          aria-current={index === 0 ? 'page' : undefined}
          className={cx(
            'shrink-0 border-b-2 px-xs pb-2 pt-1 font-medium transition duration-300 ease-standard hover:border-brand-teal hover:text-brand-teal',
            index === 0 ? 'border-brand-teal text-brand-teal' : 'border-transparent text-secondary',
          )}
          href={item.to}
          key={item.id}
        >
          {item.label}
        </a>
      ))}
    </nav>
  );
}

/**
 * Phase 1 lightweight badge / commendation model (positive only).
 *
 * Sources must be real:
 * - journey_completion
 * - thread_helpful (accepted answer or manual mark)
 * - peer_commendation (user initiated, admin reviewable)
 * - admin_award
 *
 * Rules enforced here:
 * - Positive only. No clinical ranking, patient outcomes, deficiencies, PHI.
 * - User can hide from public profile (per-profile opt-out flag, local for Phase1).
 * - Admin review path stubbed (future).
 * - Auditable source required.
 */

export type BadgeSource = 'journey_completion' | 'thread_helpful' | 'peer_commendation' | 'admin_award';

export interface CommunityBadge {
  id: string;
  label: string;
  source: BadgeSource;
  awardedAt: string;
  awardedBy?: string; // display or id
  detail?: string;
  hidden?: boolean; // user opt-out for public display
}

const BADGE_STORAGE_KEY = 'community-badges-v1';
const HIDE_STORAGE_KEY = 'community-badges-hidden-v1';

function loadBadges(): Record<string, CommunityBadge[]> {
  try {
    const raw = localStorage.getItem(BADGE_STORAGE_KEY);
    return raw ? JSON.parse(raw) : {};
  } catch {
    return {};
  }
}

function saveBadges(map: Record<string, CommunityBadge[]>) {
  try {
    localStorage.setItem(BADGE_STORAGE_KEY, JSON.stringify(map));
  } catch {}
}

function loadHidden(): Record<string, string[]> {
  try {
    return JSON.parse(localStorage.getItem(HIDE_STORAGE_KEY) || '{}');
  } catch {
    return {};
  }
}

function saveHidden(map: Record<string, string[]>) {
  try {
    localStorage.setItem(HIDE_STORAGE_KEY, JSON.stringify(map));
  } catch {}
}

/** Get badges for a user. Filters hidden for public views. */
export function getUserBadges(userId: string, viewerIsOwnerOrAdmin: boolean): CommunityBadge[] {
  const all = loadBadges()[userId] || [];
  if (viewerIsOwnerOrAdmin) return all;
  const hidden = new Set(loadHidden()[userId] || []);
  return all.filter((b) => !b.hidden && !hidden.has(b.id));
}

/** Add a badge (real source only). For demo / admin flows. */
export function awardBadge(userId: string, badge: Omit<CommunityBadge, 'id' | 'awardedAt'>) {
  const map = loadBadges();
  const list = map[userId] || [];
  const newBadge: CommunityBadge = {
    ...badge,
    id: `badge-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`,
    awardedAt: new Date().toISOString(),
  };
  map[userId] = [...list, newBadge];
  saveBadges(map);
}

/** Toggle hide for owner. */
export function setBadgeHidden(userId: string, badgeId: string, hidden: boolean) {
  const map = loadHidden();
  const list = new Set(map[userId] || []);
  if (hidden) list.add(badgeId);
  else list.delete(badgeId);
  map[userId] = Array.from(list);
  saveHidden(map);
}

/** Remove (admin / moderation). */
export function removeBadge(userId: string, badgeId: string) {
  const map = loadBadges();
  if (map[userId]) {
    map[userId] = map[userId].filter((b) => b.id !== badgeId);
    saveBadges(map);
  }
}

